function compactBreakdown(breakdown) {
  const rows = (breakdown.rows || []).map((row) => {
    const social = row.socialInsuranceBreakdown || {};
    return {
      who: row.who,
      disabled: row.disabled,
      disabilityKind: row.disabilityKind,
      salaryWan: row.salaryWan,
      employmentIncomeWan: row.employmentIncomeWan,
      employmentIncomeBaseDeductionWan: row.employmentIncomeBaseDeductionWan,
      incomeAdjustmentDeductionWan: row.incomeAdjustmentDeductionWan,
      employmentIncomeDeductionWan: row.employmentIncomeDeductionWan,
      employmentIncomeDeductionDetail: row.employmentIncomeDeductionDetail,
      socialInsuranceWan: row.socialInsuranceWan,
      socialInsuranceBreakdown: {
        healthWan: social.healthWan,
        careWan: social.careWan,
        childSupportContributionWan: social.childSupportContributionWan,
        pensionWan: social.pensionWan,
        employmentWan: social.employmentWan,
        components: { formulas: social.components?.formulas },
        sources: social.sources,
      },
    };
  });
  const taxByWho = (breakdown.tax?.byWho || []).map((row) => ({
    who: row.who,
    deductions: {
      basicITWan: row.deductions?.basicITWan,
      basicLTWan: row.deductions?.basicLTWan,
      basicITDetail: { formula: row.deductions?.basicITDetail?.formula },
      basicLTDetail: { formula: row.deductions?.basicLTDetail?.formula },
      workingStudentITWan: row.deductions?.workingStudentITWan,
      workingStudentLTWan: row.deductions?.workingStudentLTWan,
      disabilityITWan: row.deductions?.disabilityITWan,
      disabilityLTWan: row.deductions?.disabilityLTWan,
    },
    incomeTax: {
      taxableWan: row.incomeTax?.taxableWan,
      taxWan: row.incomeTax?.taxWan,
      formula: row.incomeTax?.formula,
      source: row.incomeTax?.source,
    },
    residentTax: {
      taxableWan: row.residentTax?.taxableWan,
      computedTaxWan: row.residentTax?.computedTaxWan,
      forestEnvironmentTaxYen: row.residentTax?.forestEnvironmentTaxYen,
      formula: row.residentTax?.formula,
      source: row.residentTax?.source,
    },
  }));
  const programs = breakdown.programs || {};
  const tcca = programs.tcca || {};
  const welfare = programs.welfareAllowance || {};
  const service = programs.service || {};

  return {
    salaryWan: breakdown.salaryWan,
    rows,
    deductions: breakdown.deductions,
    tax: { byWho: taxByWho },
    takeHome: { takeHomeWan: breakdown.takeHome?.takeHomeWan },
    programs: {
      tcca: {
        source: tcca.source,
        fuyoCount: tcca.fuyoCount,
        head: {
          judgmentIncome: {
            deductions: tcca.head?.judgmentIncome?.deductions,
            deductionSumWan: tcca.head?.judgmentIncome?.deductionSumWan,
          },
        },
        headAdjustedIncomeYen: tcca.headAdjustedIncomeYen,
        headLimitYen: tcca.headLimitYen,
        familyMaxAdjustedIncomeYen: tcca.familyMaxAdjustedIncomeYen,
        familyLimitYen: tcca.familyLimitYen,
        eligible: tcca.eligible,
        monthlyYen: tcca.monthlyYen,
        annualWan: tcca.annualWan,
        formulas: tcca.formulas,
      },
      welfareAllowance: {
        source: welfare.source,
        fuyoCount: welfare.fuyoCount,
        obligorJudgmentIncomeDetails: (welfare.obligorJudgmentIncomeDetails || []).map((detail) => ({
          adjustedYen: detail.adjustedYen,
          deductionSumWan: detail.deductionSumWan,
          deductions: detail.deductions,
        })),
        obligorMaxAdjustedIncomeYen: welfare.obligorMaxAdjustedIncomeYen,
        obligorLimitYen: welfare.obligorLimitYen,
        obligorOk: welfare.obligorOk,
        recipients: welfare.recipients,
        monthlyYen: welfare.monthlyYen,
        annualWan: welfare.annualWan,
        formulas: welfare.formulas,
      },
      service: {
        confidence: service.confidence,
        householdLevySumWan: service.householdLevySumWan,
        taxCollectionHouseholdLevySumWan: service.taxCollectionHouseholdLevySumWan,
        assessmentLevyByWho: service.assessmentLevyByWho,
        use: service.use,
        details: (service.details || []).map((detail) => ({
          who: detail.who,
          monthlyUpperYen: detail.monthlyUpperYen,
          confidence: detail.confidence,
          formula: detail.formula,
          sources: detail.sources,
        })),
        monthlyTotalYen: service.monthlyTotalYen,
        annualWan: service.annualWan,
        calculation: service.calculation,
      },
      m01: programs.m01,
      n04: programs.n04,
    },
    allowance: breakdown.allowance,
    costBurden: breakdown.costBurden,
    disposable: breakdown.disposable,
  };
}

function enumerateFamilyProfiles() {
  const profiles = [];
  for (let n = 1; n <= 3; n += 1) {
    for (let a = 0; a <= n; a += 1) {
      for (let b = 0; b <= n - a; b += 1) {
        for (let c = 0; c <= n - a - b; c += 1) {
          const d = a + b + c;
          if (d === 0) continue;
          profiles.push({
            id: `N${n}-A${a}B${b}C${c}`,
            total_children: n,
            disabled_children: d,
            qualification_counts: { A: a, B: b, C: c },
            independent_tax_disability_counts: { ordinary: a, cohabiting_special: b + c, none: n - d },
            nondisabled_children: n - d,
            label: `子ども${n}人・A${a}/B${b}/C${c}・非障害児${n - d}人`,
          });
        }
      }
    }
  }
  return profiles;
}

function multiplyKnown(value, count) {
  return Number.isFinite(value) && value >= 0 ? value * count : null;
}

function makeRevisionChildren(family) {
  const children = [];
  for (const state of ["A", "B", "C", "none"]) {
    const count = state === "none" ? family.nondisabled_children : family.qualification_counts[state];
    for (let i = 0; i < count; i += 1) {
      children.push({
        id: `${state}-${i + 1}`,
        age: 7,
        cohabit: true,
        disabled: state !== "none",
        specialDisabled: state === "B" || state === "C",
        tccaGrade: state === "none" ? "not" : state === "A" ? "2" : "1",
        childWelfareAllowance: state === "C",
        salaryWan: 0,
        otherIncomeWan: 0,
      });
    }
  }
  return children;
}

function makeRevisionEducationProfile(family, needInputs) {
  const householdSize = family.total_children + 2;
  const disabilityParts = ["A", "B", "C"].filter((state) => family.qualification_counts[state] > 0)
    .map((state) => multiplyKnown(needInputs.monthlyDisabilityAdditionByStatusYen?.[state], family.qualification_counts[state]));
  const disabilityAdditionYen = disabilityParts.every(Number.isFinite) ? disabilityParts.reduce((sum, value) => sum + value, 0) : null;
  return {
    schemaVersion: 1,
    fiscalYear: 2026,
    schoolType: "special-needs-school",
    department: "elementary",
    enrollment: "day",
    schoolYear: "通常年（新入学用品・修学旅行を計上しない）",
    expenses: [{ id: "school-supplies", annualExpenseYen: 11640, valueType: "補助上限に達する対象実費を仮定した条件値。実測平均ではない" }],
    needMeasurement: {
      basisDate: "2025-12-31",
      gradeArea: "1-2",
      winterRegion: "VI",
      educationChildrenCount: family.total_children,
      annualYearEndAssistanceYen: needInputs.annualYearEndAssistanceYenByHouseholdSize?.[householdSize] ?? null,
      monthlyTransitionalAdditionYen: needInputs.monthlyTransitionalAdditionYenByHouseholdSize?.[householdSize] ?? null,
      monthlySpecialAdditionYen: multiplyKnown(needInputs.monthlySpecialAdditionPerPersonYen, householdSize),
      monthlyDisabilityAdditionYen: disabilityAdditionYen,
      monthlySingleParentAdditionYen: needInputs.monthlySingleParentAdditionYen,
      annualSchoolMaterialsYen: multiplyKnown(needInputs.annualSchoolMaterialsPerChildYen, family.total_children),
      annualSchoolLunchBudgetYen: multiplyKnown(needInputs.annualSchoolLunchBudgetPerChildYen, family.total_children),
      previousAnnualCommuteYen: multiplyKnown(needInputs.previousAnnualCommutePerChildYen, family.total_children),
      monthlyHousingYen: needInputs.monthlyHousingYen,
      inputEvidence: needInputs.inputEvidence || {},
    },
  };
}

function generateRevisionScenarios({ needInputs = REVISION_NEED_INPUTS } = {}) {
  const familyProfiles = enumerateFamilyProfiles();
  const spouseSalaries = [0, 200, 400];
  const serviceAmounts = [4600, 10406, 37200];
  const conditions = [];
  for (const family of familyProfiles) {
    for (const spouseSalary of spouseSalaries) {
      for (const serviceAmount of serviceAmounts) {
        const children = makeRevisionChildren(family);
        const n04EducationProfile = makeRevisionEducationProfile(family, needInputs);
        const blockingIssues = validateN04EducationProfile(n04EducationProfile);
        conditions.push({
          id: `${family.id}-S${spouseSalary}-R${serviceAmount}`,
          family_profile_id: family.id,
          spouse_salary_wan: spouseSalary,
          service_use_yen_per_child_month: serviceAmount,
          calculation_status: blockingIssues.length ? "blocked" : "conditions-ready-results-pending",
          blocking_issues: blockingIssues,
          household: {
            head: { age: 45, salaryWan: 0 },
            spouseEnabled: true,
            spouse: { age: 45, salaryWan: spouseSalary },
            children,
            programs: {
              m01: false,
              n04: true,
              n04Count: family.disabled_children,
              n04EducationProfile,
              serviceUse: {
                schemaVersion: 1,
                monthlyBurdenBeforeCapByChildYen: children.map((child) => child.disabled ? serviceAmount : 0),
                months: 12,
              },
            },
          },
          result: null,
        });
      }
    }
  }
  assert.equal(familyProfiles.length, 31);
  assert.equal(conditions.length, 279);
  assert.equal(new Set(conditions.map((condition) => condition.id)).size, 279);
  assert.deepEqual([1, 2, 3].map((n) => familyProfiles.filter((family) => family.total_children === n).length), [3, 9, 19]);
  return {
    schema_version: "1.0.0",
    title: "改稿用・モデル世帯の条件設計（従来3ケースとは独立）",
    checked_on: "2026-11-15",
