      source: N04_FUNABASHI_SOURCE,
    },
    needAmountWan: monthlyNeedYen / 10000,
    ratio,
    confidence: "provisional",
  };
}

function salaryIncomeBeforeAdjustmentYen(grossYen, incomeYear) {
  if (!Number.isSafeInteger(grossYen) || grossYen < 0) throw new RangeError("給与収入には0以上の整数円が必要です。");
  if (incomeYear !== 2025 && incomeYear !== 2026) throw new RangeError("給与所得は令和7・8年分のみ対応しています。");
  if (incomeYear === 2025) {
    if (grossYen < 651000) return 0;
    if (grossYen < 1900000) return grossYen - 650000;
  } else {
    if (grossYen < 741000) return 0;
    if (grossYen < 2191000) return grossYen - 740000;
    if (grossYen < 2193000) return 1451000;
    if (grossYen < 2196000) return 1453000;
    if (grossYen < 2200000) return 1456000;
  }
  // 4000円ごとの階級下端に70%／80%を掛ける。元の給与に直接掛けない。
  if (grossYen < 3600000) return Math.floor(grossYen / 4000) * 2800 - 80000;
  if (grossYen < 6600000) return Math.floor(grossYen / 4000) * 3200 - 440000;
  if (grossYen < 8500000) return Math.floor(grossYen * 9 / 10) - 1100000;
  return grossYen - 1950000;
}

function childOrDisabilityIncomeAdjustmentYen(grossYen, eligible) {
  if (!Number.isSafeInteger(grossYen) || grossYen < 0 || typeof eligible !== "boolean") {
    throw new RangeError("給与収入（整数円）と控除の適用可否が必要です。");
  }
  if (!eligible || grossYen <= 8500000) return 0;
  return Math.ceil((Math.min(grossYen, 10000000) - 8500000) / 10);
}

function priorEarnedIncome(salaryWan, fiscalYear) {
  const y=salaryWan*10000, unit=Math.floor(y/4000);
  let gross;
  if(fiscalYear===2026) gross=salaryIncomeBeforeAdjustmentYen(y,2025);
  else if(y<=1620000) gross=Math.max(0,y-550000);
  else if(y<1800000) gross=unit*2400+100000;
  else if(y<3600000) gross=unit*2800-80000;
  else if(y<6600000) gross=unit*3200-440000;
  else if(y<=8500000) gross=y*9/10-1100000;
  else gross=y-1950000;
  // 2親とも23歳未満の子あり。税の扶養控除の申告先とは別（国税庁 No.1411）。
  return gross-childOrDisabilityIncomeAdjustmentYen(y,true);
}

function categoryAnnualYen([bps,flat,cap],basisYen,doubleCount,remainingTenths) {
  const tenThousandthsOfYen=basisYen*bps+flat*doubleCount*remainingTenths*500;
  return Math.min(cap,Math.floor(tenThousandthsOfYen/100000)*10);
}

function estimateFunabashiNational({fiscalYear,headWan,spouseWan,nationalRoles,children,payer,standardPension}={}) {
  const reasons=[];
  if (![2025,2026].includes(fiscalYear)) reasons.push("船橋市国保の対応年度は令和7・8年度です。");
  if (![headWan,spouseWan].every(v=>Number.isSafeInteger(v)&&v>=0&&v<=1500)) reasons.push("給与は0～1,500万円の整数を指定してください。");
  if (!Array.isArray(nationalRoles)||!nationalRoles.length||new Set(nationalRoles).size!==nationalRoles.length||
      !nationalRoles.every(r=>roles.includes(r))) reasons.push("国保に通年加入する親を指定してください。");
  if (!Array.isArray(children)||children.length<1||children.length>3||!children.every(c=>c && Number.isInteger(c.age)&&c.age>=0&&c.age<=17&&typeof c.national==="boolean"))
    reasons.push("各児の年度初年齢と、国保への加入の有無を指定してください。");
  if (!roles.includes(payer)) reasons.push("世帯の国保保険料を実際に支払う親を指定してください。");
  if (standardPension!==true) reasons.push("国民年金第1号の通常納付（免除・猶予・前納なし）が前提です。該当しなければ実払額を用いてください。");
  if(reasons.length) return {known:false,reasons,healthYen:null,pensionYen:null,byPayer:null,breakdown:null};
  const r=RATE[fiscalYear], wages={head:headWan,spouse:spouseWan};
  const income={head:priorEarnedIncome(headWan,fiscalYear),spouse:priorEarnedIncome(spouseWan,fiscalYear)};
  const nationalChildren=children.filter(c=>c.national), insuredCount=nationalRoles.length+nationalChildren.length;
  // 均等割軽減の判定には擬制世帯主の所得も含む。世帯主でない未加入の配偶者は含めない。
  const tested=roles.filter(role=>role==="head"||nationalRoles.includes(role));
  const judgedIncomeYen=tested.reduce((sum,role)=>sum+income[role],0);
  const earnerAdjustment=100000*Math.max(0,tested.filter(role=>wages[role]>55).length-1);
  const base=430000+earnerAdjustment;
  const remaining=judgedIncomeYen<=base ? 3 : judgedIncomeYen<=base+r.half*insuredCount ? 5 : judgedIncomeYen<=base+r.fifth*insuredCount ? 8 : 10;
  const insuredBasisYen=nationalRoles.reduce((sum,role)=>sum+Math.max(0,income[role]-430000),0);
  const units=insuredCount*2-nationalChildren.filter(c=>c.age<6).length;
  // 児童に所得なし：介護分・子育て分の所得割基礎もこの場合は成人の賦課基準額と一致。
  const medical=categoryAnnualYen(r.medical,insuredBasisYen,units,remaining);
  const elderly=categoryAnnualYen(r.elderly,insuredBasisYen,units,remaining);
  const care=categoryAnnualYen(r.care,insuredBasisYen,nationalRoles.length*2,remaining);
  const childSupport=categoryAnnualYen(r.childSupport,insuredBasisYen,nationalRoles.length*2,remaining);
  const healthYen=medical+elderly+care+childSupport;
  const pensionYen={head:0,spouse:0};
  for(const role of nationalRoles) pensionYen[role]=12*r.pensionMonthly;
  const byPayer={...pensionYen};
  byPayer[payer]+=healthYen;
  return {known:true,reasons:[],healthYen,pensionYen,byPayer,breakdown:{
    fiscalYear,ageBasis:"固定した年度初年齢",incomeYear:fiscalYear-1,income,judgedIncomeYen,insuredBasisYen,insuredCount,
    lowIncomeReductionPercent:100-10*remaining,medical,elderly,care,childSupport,payer,
  }};
}

function buildHousehold(caseHousehold = {}) {
  const headInput = caseHousehold.head || {};
  const spouseInput = caseHousehold.spouse || {};
  const childrenInput = Array.isArray(caseHousehold.children) ? caseHousehold.children : [];
  const programsInput = caseHousehold.programs || {};
  if (programsInput.n04EducationProfile && !(caseHousehold.n04 || caseHousehold.n04Enabled || programsInput.n04 || programsInput.n04Enabled)) {
    throw new RangeError("n04EducationProfile requires programs.n04=true; an explicit education expense must not become zero silently");
  }

  const head = {
    age: toNumber(headInput.age, 40),
    salaryWan: toNumber(headInput.salaryWan, 0),
    disabled: Boolean(headInput.disabled),
    disabilityKind: headInput.disabilityKind || (headInput.specialDisabled ? "special" : "disabled"),
    tokubetsuAllowance: Boolean(headInput.tokubetsuAllowance),
    childWelfareAllowance: Boolean(headInput.childWelfareAllowance),
    basicDisabilityPensionGrade: String(headInput.basicDisabilityPensionGrade || "none"),
    basicDisabilityPensionPre20: Boolean(headInput.basicDisabilityPensionPre20),
    otherIncomeWan: toNumber(headInput.otherIncomeWan, 0),
    widowWan: toNumber(headInput.widowWan, 0),
    singleParentWan: toNumber(headInput.singleParentWan, 0),
    singleParentTaxRole: headInput.singleParentTaxRole || null,
    workingStudentWan: toNumber(headInput.workingStudentWan, 0),
    otherDedWan: toNumber(headInput.otherDedWan, 0),
  };

  const spouse = {
    age: toNumber(spouseInput.age, 40),
    salaryWan: toNumber(spouseInput.salaryWan, 0),
    otherIncomeWan: toNumber(spouseInput.otherIncomeWan, 0),
    workingStudentWan: toNumber(spouseInput.workingStudentWan, 0),
    disabled: Boolean(spouseInput.disabled),
    disabilityKind: spouseInput.disabilityKind || (spouseInput.specialDisabled ? "special" : "disabled"),
    tokubetsuAllowance: Boolean(spouseInput.tokubetsuAllowance),
    childWelfareAllowance: Boolean(spouseInput.childWelfareAllowance),
    basicDisabilityPensionGrade: String(spouseInput.basicDisabilityPensionGrade || "none"),
    basicDisabilityPensionPre20: Boolean(spouseInput.basicDisabilityPensionPre20),
  };

  const children = childrenInput.map((c, i) => ({
    id: c.id || `fixture_child_${i + 1}`,
    age: toNumber(c.age, 0),
    cohabit: c.cohabit !== false,
    disabled: Boolean(c.disabled),
    specialDisabled: Boolean(c.specialDisabled),
    tccaGrade: String(c.tccaGrade || "not"),
    childWelfareAllowance: Boolean(c.childWelfareAllowance),
    tokubetsuAllowance: Boolean(c.tokubetsuAllowance),
    workingStudent: Boolean(c.workingStudent),
    salaryWan: toNumber(c.salaryWan, 0),
    otherIncomeWan: toNumber(c.otherIncomeWan, 0),
  }));

  return {
    head,
    spouseEnabled: Boolean(caseHousehold.spouseEnabled),
    spouse,
    children,
    programs: {
      m01: Boolean(caseHousehold.m01 || caseHousehold.m01Enabled || programsInput.m01 || programsInput.m01Enabled),
      m01AnnualYen: toNumber(programsInput.m01AnnualYen, M01_KENSHIN_ANNUAL_YEN_DEFAULT),
      m01Count: Math.max(1, Math.trunc(toNumber(programsInput.m01Count, 1))),
      n04: Boolean(caseHousehold.n04 || caseHousehold.n04Enabled || programsInput.n04 || programsInput.n04Enabled),
      n04Count: Math.max(1, Math.trunc(toNumber(programsInput.n04Count, 1))),
      n04HousingYen: toNumber(programsInput.n04HousingYen, N04_NEED_R7.housingYen),
      ...(programsInput.n04EducationProfile ? { n04EducationProfile: programsInput.n04EducationProfile } : {}),
      ...(programsInput.serviceUse ? { serviceUse: programsInput.serviceUse } : {}),
    },
  };
}

function getConfig(tables, key) {
  return tables?.configs?.[key] || tables?.[key] || {};
}

function createContext({ household, scenario, tables }) {
  const configs = getRequiredTables(tables);
  const skey = normalizeScenario(scenario);
  if (skey === "s4") {
    // R8年分所得税・R9年度住民税。旧scenarioの設定JSONは上書きしない。
    configs.dependentDeductionCfg = { ...configs.dependentDeductionCfg, dependent_total_income_max_wan: 62 };
    for (const key of ["spouseDeductionITCfg", "spouseDeductionLTCfg"]) {
      const cfg = configs[key];
      configs[key] = {
        ...cfg, spouse_total_income_max_wan: 62,
        head_total_income_bands_wan: (cfg.head_total_income_bands_wan || []).map((b, i, all) => ({
          ...b, ...(i ? { min_exclusive_wan: all[i - 1].max_wan } : {}),
        })),
      };
    }
    for (const key of ["spouseSpecialDeductionITCfg", "spouseSpecialDeductionLTCfg"]) {
      const cfg = configs[key];
      configs[key] = { ...cfg, head_total_income_bands_wan: (cfg.head_total_income_bands_wan || []).map((b, i, all) => ({
        ...b,
        ...(i ? { head_min_exclusive_wan: all[i - 1].head_max_wan } : {}),
        spouse_bands_wan: (b.spouse_bands_wan || []).map((s, j, bands) => ({
          ...s, spouse_min_exclusive_wan: j ? bands[j - 1].spouse_max_wan : 62,
        })),
      })) };
    }
    for (const key of ["specialKinDeductionITCfg", "specialKinDeductionLTCfg"]) {
      const cfg = configs[key];
      configs[key] = { ...cfg, child_total_income_bands_wan: (cfg.child_total_income_bands_wan || []).map((b, i, all) => ({
        ...b, min_exclusive_wan: i ? all[i - 1].max_wan : 62,
      })) };
    }
  }
  return {
    ...configs,
    ...household,
    skey,
    empKey: `emp_${skey === "s4" ? "s3" : skey}`,
    basicITKey: `basicIT_${skey === "s4" ? "s3" : skey}`,
    socialKey: `social_${skey === "s4" ? "s3" : skey}`,
    taxDependentIncomeMaxWan: skey === "s4" ? 62 : 58,
    allowanceDependentIncomeMaxWan: 58,
    taxYear: skey === "s4" ? 2026 : null,
    residentTaxAssessmentYear: skey === "s4" ? 2027 : null,
    wsAmtIT: toNumber(configs.workingStudentDeductionCfg?.amount_it_wan, 0),
    wsAmtLT: toNumber(configs.workingStudentDeductionCfg?.amount_lt_wan, 0),
  };
}

function calcOne(ctx, age, salaryWan, otherIncomeWan, opts = {}) {
  const s = Math.max(0, toNumber(salaryWan, 0));
  const o = Math.max(0, toNumber(otherIncomeWan, 0));
  const r = rowAtKeyInt(ctx.empStatic, "x", Math.round(s));
  const empBaseWan = ctx.skey === "s4" ? calcEmploymentIncomeDeductionR8FinalWan(s) : toNumber(r?.[ctx.empKey], 0);
  const incomeAdjWan = toNumber(opts?.incomeAdjWan, 0);
  const empWan = empBaseWan + incomeAdjWan;
  const incomeWan = Math.max(0, s - empWan);
  const totalIncomeWan = incomeWan + o;

  const exemptSocial = Boolean(opts?.exemptSocialUnder130) && s <= 130;
  const socialComponents = calculateSocialInsuranceComponents(s, age, ctx.skey);
  const socialWan = exemptSocial ? 0 : socialComponents.totalWan;

  const basicITRow = rowAtKeyInt(ctx.basicITStatic, "income_axis", Math.round(totalIncomeWan));
  const basicLTRow = rowAtKeyInt(ctx.basicLTStatic, "income_axis", Math.round(totalIncomeWan));
  const basicITWan = ctx.skey === "s4" ? calcBasicIncomeTaxDeductionR8FinalWan(totalIncomeWan) : toNumber(basicITRow?.[ctx.basicITKey], 0);
  const basicLTWan = ctx.skey === "s4"
    ? totalIncomeWan <= 2400 ? 43 : totalIncomeWan <= 2450 ? 29 : totalIncomeWan <= 2500 ? 15 : 0
    : toNumber(basicLTRow?.basicLT_common, 0);

  return {
    salaryWan: s,
    empWan,
    empBaseWan,
    incomeAdjWan,
    incomeWan,
    otherIncomeWan: o,
    totalIncomeWan,
    socialWan,
    basicITWan,
    basicLTWan,
    employmentIncomeDeductionDetail: describeEmploymentIncomeDeduction(s, ctx.skey, empBaseWan, incomeAdjWan),
    basicDeductionDetail: {
      incomeTax: describeBasicDeduction("it", ctx.skey, totalIncomeWan, basicITWan),
      residentTax: describeBasicDeduction("lt", ctx.skey, totalIncomeWan, basicLTWan),
    },
    socialInsuranceDetail: {
      ...describeSocialInsuranceDeduction(s, age, ctx.skey, socialWan, exemptSocial),
      tableKey: ctx.socialKey,
      table: toNumber(age, 0) >= 40 ? "socialO40" : "socialU40",
      exemptUnder130: exemptSocial,
      healthWan: exemptSocial ? 0 : socialComponents.healthWan,
      careWan: exemptSocial ? 0 : socialComponents.careWan,
      pensionWan: exemptSocial ? 0 : socialComponents.pensionWan,
      employmentWan: exemptSocial ? 0 : socialComponents.employmentWan,
      childSupportContributionWan: exemptSocial ? 0 : socialComponents.childSupportContributionWan,
      sources: {
        healthCarePensionSupport: CALCULATION_SOURCES.socialHealth,
        employment: CALCULATION_SOURCES.employmentInsurance,
      },
    },
  };
}

function buildRows(ctx, headSalaryWan) {
  const { head, spouse, spouseEnabled, children } = ctx;
  const rows = [];
  rows.push({
    who: "世帯主",
    age: head.age,
    workingStudent: Boolean(head.workingStudentWan),
    disabled: Boolean(head.disabled),
    tccaSpecial: Boolean(head.disabled) && head.disabilityKind === "special",
    cohabit: true,
    otherDedWan: toNumber(head.otherDedWan, 0),
    widowWan: toNumber(head.widowWan, 0),
    singleParentWan: toNumber(head.singleParentWan, 0),
    tccaDisWan: head.disabled ? (head.disabilityKind === "special" ? 40 : 27) : 0,
    welfareDisWan: head.disabled ? (head.disabilityKind === "special" ? 40 : 27) : 0,
    ...calcOne(ctx, head.age, headSalaryWan, head.otherIncomeWan, { exemptSocialUnder130: false, incomeAdjWan: 0 }),
  });
  if (spouseEnabled) {
    rows.push({
      who: "配偶者",
      age: spouse.age,
      workingStudent: Boolean(spouse.workingStudentWan),
      disabled: Boolean(spouse.disabled),
      tccaSpecial: Boolean(spouse.disabled) && spouse.disabilityKind === "special",
      cohabit: true,
      tccaDisWan: spouse.disabled ? (spouse.disabilityKind === "special" ? 40 : 27) : 0,
      welfareDisWan: spouse.disabled ? (spouse.disabilityKind === "special" ? 40 : 27) : 0,
      ...calcOne(ctx, spouse.age, spouse.salaryWan, spouse.otherIncomeWan, { exemptSocialUnder130: true, incomeAdjWan: 0 }),
    });
  }
  children.forEach((c, i) =>
    rows.push({
      who: `子ども${i + 1}`,
      age: c.age,
      workingStudent: Boolean(c.workingStudent),
      disabled: Boolean(c.disabled),
      tccaSpecial: Boolean(c.disabled) && Boolean(c.specialDisabled),
      cohabit: c?.cohabit !== false,
      tccaGrade: String(c?.tccaGrade || "not"),
      tccaDisWan: c.disabled ? (c.specialDisabled ? 40 : 27) : 0,
      welfareDisWan: c.disabled ? (c.specialDisabled ? 40 : 27) : 0,
      ...calcOne(ctx, c.age, c.salaryWan, c.otherIncomeWan, { exemptSocialUnder130: true, incomeAdjWan: 0 }),
    })
  );

  const childDepMaxWan = toNumber(ctx.taxDependentIncomeMaxWan, 58);
  const dependentChildren = rows.filter(
    (r) => String(r?.who || "").startsWith("子ども") && toNumber(r?.totalIncomeWan, 0) <= childDepMaxWan
  );
  const hasDependentUnder23 = dependentChildren.some((r) => toNumber(r?.age, 0) < 23);
  const hasDependentSpecialDisabled = dependentChildren.some((r) => Boolean(r?.tccaSpecial));
  const headIsSpecialDisabled = Boolean(head.disabled) && head.disabilityKind === "special";
  const spouseIsSpecialDisabled = Boolean(spouseEnabled && spouse.disabled) && spouse.disabilityKind === "special";
  const headEligible = headIsSpecialDisabled || spouseIsSpecialDisabled || hasDependentUnder23 || hasDependentSpecialDisabled;
  const spouseEligible = spouseIsSpecialDisabled || headIsSpecialDisabled || hasDependentUnder23 || hasDependentSpecialDisabled;

  const headAdjWan = calcIncomeAdjustmentDeductionWan(headSalaryWan, headEligible);
  const spouseAdjWan = spouseEnabled ? calcIncomeAdjustmentDeductionWan(spouse.salaryWan, spouseEligible) : 0;

  if (headAdjWan > 0) {
    const idx = rows.findIndex((r) => r.who === "世帯主");
    if (idx >= 0) {
      rows[idx] = {
        ...rows[idx],
        ...calcOne(ctx, head.age, headSalaryWan, head.otherIncomeWan, {
          exemptSocialUnder130: false,
          incomeAdjWan: headAdjWan,
        }),
      };
    }
  }
  if (spouseEnabled && spouseAdjWan > 0) {
    const idx = rows.findIndex((r) => r.who === "配偶者");
    if (idx >= 0) {
      rows[idx] = {
        ...rows[idx],
        ...calcOne(ctx, spouse.age, spouse.salaryWan, spouse.otherIncomeWan, {
          exemptSocialUnder130: true,
          incomeAdjWan: spouseAdjWan,
        }),
      };
    }
  }
  if (ctx.skey === "s4") {
    for (const row of rows) {
      row.workingStudent = Boolean(row.workingStudent) && row.totalIncomeWan <= 89 && row.otherIncomeWan <= 10;
    }
  }
  return rows;
}

function employeeDeduction(numerator, denominator) {
  const whole = Math.floor(numerator / denominator);
  return whole + Number(2 * (numerator % denominator) > denominator);
}

function checkAnnualPay(yen) {
  if (!Number.isSafeInteger(yen) || yen < 0 || yen > MAX_ANNUAL_YEN)
    throw new RangeError("各人の給与年収は0～15,000,000円の整数で指定してください。");
}

function insuredPerson(annualYen) {
  // 旧年度と共有するのは健保の等級表だけ。旧年度の厚年32級上限・率・加入判定は使わない。
  const {healthGrade, healthStandardYen} = employeeGradesFromAnnualPay(annualYen);
  // 健保4級～38級に対応する厚年1級～35級。上下端以外の報酬帯は共通。
  const pensionGrade = Math.min(35, Math.max(1, healthGrade - 3));
  const pensionStandardYen = Math.min(750000, Math.max(88000, healthStandardYen));
  const healthCareSupportYen = employeeDeduction(
    healthStandardYen * (policy.healthBps + policy.careBps + policy.childSupportBps), 2 * BPS);
  const pensionYen = employeeDeduction(pensionStandardYen * policy.pensionBps, 2 * BPS);
  // 雇用保険は標準報酬でなく実際の賃金。年収/12を先に丸めず、本人率を掛けた月額を丸める。
  const employmentYen = employeeDeduction(annualYen * policy.employeeEmploymentBps, MONTHS * BPS);
  const totalYen = healthCareSupportYen + pensionYen + employmentYen;
  return {
    status:"employee", annualPayYen:annualYen, healthGrade, healthStandardYen, pensionGrade, pensionStandardYen,
    monthly:{healthCareSupportYen, pensionYen, employmentYen, totalYen},
    annual:{healthCareSupportYen:MONTHS*healthCareSupportYen, pensionYen:MONTHS*pensionYen,
      employmentYen:MONTHS*employmentYen, totalYen:MONTHS*totalYen},
  };
}

function dependentPerson() {
  const zero = {healthCareSupportYen:0, pensionYen:0, employmentYen:0, totalYen:0};
  return {status:"dependent", annualPayYen:0, healthGrade:null, healthStandardYen:null,
    pensionGrade:null, pensionStandardYen:null, monthly:{...zero}, annual:{...zero}};
}

function calculateHouseholdInsurance2029({headAnnualYen, spouseAnnualYen} = {}) {
  checkAnnualPay(headAnnualYen);
  checkAnnualPay(spouseAnnualYen);
  if (headAnnualYen === 0 && spouseAnnualYen === 0)
    return {status:"excluded", reason:"both-nonworking", head:null, spouse:null, totalYen:null, policy};
  const head = headAnnualYen > 0 ? insuredPerson(headAnnualYen) : dependentPerson();
  const spouse = spouseAnnualYen > 0 ? insuredPerson(spouseAnnualYen) : dependentPerson();
  return {status:"calculated", head, spouse, totalYen:head.annual.totalYen+spouse.annual.totalYen, policy};
}

function unitInterval(value) {
  return Math.max(0, Math.min(1, value));
}

function requireFiniteNumber(value, name) {
  if (typeof value !== "number" || !Number.isFinite(value)) throw new TypeError(`${name}は有限の数値が必要です。`);
  return value;
}

function computeIllustrativeAdjustment(series, options) {
  const { needAnnualWan, eligibleExpenseAnnualWan, lowerRatio = 1.5, upperRatio = 2.5, burdenRate = 0.1 } = options || {};
  for (const [name, value] of Object.entries({ needAnnualWan, eligibleExpenseAnnualWan, lowerRatio, upperRatio, burdenRate })) requireFiniteNumber(value, name);
  if (!(needAnnualWan > 0) || !(eligibleExpenseAnnualWan >= 0) || !(upperRatio > lowerRatio) || !(burdenRate >= 0)) throw new RangeError("調整例の需要額・対象支出・比率の条件が不正です。");
  if (!Array.isArray(series) || !series.length) throw new RangeError("現行制度系列が必要です。");
  /** 総現金給付から取り出す調整対象の二手当額。欠損は未受給0円と区別する。 */
  const direct = (point) => requireFiniteNumber(point.breakdown?.allowance?.tccaWan, "特児額") + requireFiniteNumber(point.breakdown?.allowance?.welfareAllowanceWan, "障害児福祉手当額");
  const fullSupportAnnualWan = Math.max(...series.map(direct));
  const points = series.map((point) => {
    const allowance = point.breakdown?.allowance || {};
    const otherCashAnnualWan = requireFiniteNumber(allowance.totalWan, "現金給付合計") - direct(point);
    const takeHomeAnnualWan = requireFiniteNumber(point.breakdown?.takeHome?.takeHomeWan, "手取額");
    const beforeSupportAnnualWan = takeHomeAnnualWan + otherCashAnnualWan;
    const supportRatio = beforeSupportAnnualWan / needAnnualWan;
    const supportTransition = unitInterval((supportRatio - lowerRatio) / (upperRatio - lowerRatio));
    const supportAnnualWan = fullSupportAnnualWan * (1 - supportTransition);
    const afterSupportAnnualWan = beforeSupportAnnualWan + supportAnnualWan;
    const burdenRatio = afterSupportAnnualWan / needAnnualWan;
    const burdenTransition = unitInterval((burdenRatio - lowerRatio) / (upperRatio - lowerRatio));
    const burdenCapAnnualWan = burdenRate * needAnnualWan * burdenTransition;
    const finalBurdenAnnualWan = Math.min(eligibleExpenseAnnualWan, burdenCapAnnualWan);
    const refundAnnualWan = eligibleExpenseAnnualWan - finalBurdenAnnualWan;
    const disposableAnnualWan = afterSupportAnnualWan - finalBurdenAnnualWan;
    const currentDisposableAnnualWan = requireFiniteNumber(point.disposable, "現行可処分所得");
    return { x: requireFiniteNumber(point.x, "給与収入"), beforeSupportAnnualWan, supportRatio, supportTransition, supportAnnualWan, afterSupportAnnualWan, burdenRatio, burdenTransition, burdenCapAnnualWan, finalBurdenAnnualWan, refundAnnualWan, disposableAnnualWan, currentDisposableAnnualWan, differenceAnnualWan: disposableAnnualWan - currentDisposableAnnualWan };
  });
  return { kind: "illustrative-not-optimal", needAnnualWan, eligibleExpenseAnnualWan, fullSupportAnnualWan, lowerRatio, upperRatio, burdenRate, populationWeights: null, points, impact: summarizeAdjustmentImpact(points) };
}

function summarizeAdjustmentImpact(points) {
  if (!points.length) return { minimumDifferenceAnnualWan: null, maximumDifferenceAnnualWan: null, lowerIncomeIntervals: [] };
  const lowerIncomeIntervals = [];
  let interval = null;
  for (const point of points) {
    if (point.differenceAnnualWan < -1e-9) {
      if (!interval) interval = { fromSalaryWan: point.x, toSalaryWan: point.x, minimumDifferenceAnnualWan: point.differenceAnnualWan };
      else { interval.toSalaryWan = point.x; interval.minimumDifferenceAnnualWan = Math.min(interval.minimumDifferenceAnnualWan, point.differenceAnnualWan); }
    } else if (interval) { lowerIncomeIntervals.push(interval); interval = null; }
  }
  if (interval) lowerIncomeIntervals.push(interval);
  return { minimumDifferenceAnnualWan: Math.min(...points.map((point) => point.differenceAnnualWan)), maximumDifferenceAnnualWan: Math.max(...points.map((point) => point.differenceAnnualWan)), lowerIncomeIntervals };
}

function calcM01Detail(ctx, householdLevySumWan) {
  if (!ctx.programs?.m01) {
    return {
      enabled: false,
      status: "対象外",
      householdLevyWan: toNumber(householdLevySumWan, 0),
      cutoffWan: M01_LEVY_CUTOFF_YEN / 10000,
      eligible: false,
      count: 0,
      annualWan: 0,
      confidence: "representative",
    };
  }
  const configured = toNumber(ctx.programs?.m01AnnualYen, M01_KENSHIN_ANNUAL_YEN_DEFAULT);
  const annualYenPerRecipient = Math.min(
    M01_KENSHIN_ANNUAL_YEN_RANGE.max,
    Math.max(M01_KENSHIN_ANNUAL_YEN_RANGE.min, configured)
  );
  const householdLevyYen = toNumber(householdLevySumWan, 0) * 10000;
  const eligible = householdLevyYen < M01_LEVY_CUTOFF_YEN;
  const count = Math.max(1, Math.trunc(toNumber(ctx.programs?.m01Count, 1)));
  const annualWan = eligible ? (annualYenPerRecipient * count) / 10000 : 0;
  return {
    enabled: true,
    status: eligible ? "該当" : "非該当",
    householdLevyWan: toNumber(householdLevySumWan, 0),
    cutoffWan: M01_LEVY_CUTOFF_YEN / 10000,
    eligible,
    count,
    annualYenPerRecipient,
    annualWan,
    fullReliefWan: (annualYenPerRecipient * count) / 10000,
    medicalCostBurdenWan: eligible ? 0 : (annualYenPerRecipient * count) / 10000,
    sensitivityRangeWan: {
      min: (M01_KENSHIN_ANNUAL_YEN_RANGE.min * count) / 10000,
      max: (M01_KENSHIN_ANNUAL_YEN_RANGE.max * count) / 10000,
    },
    judgment: {
      householdLevyWan: toNumber(householdLevySumWan, 0),
      householdLevyYen,
      cutoffYen: M01_LEVY_CUTOFF_YEN,
      eligible,
      comparisonOperator: "<",
      assessmentUnit: "医療保険単位の世帯",
      taxBasis: "市町村民税所得割",
      levyFormula: "（A6 − 均等割）× 60%（市町村分合計）",
      cutoffFormula: `固定基準額（市町村民税所得割 ${M01_LEVY_CUTOFF_YEN.toLocaleString("ja-JP")}円）`,
      formula: `${Math.round(householdLevyYen).toLocaleString("ja-JP")}円 < ${M01_LEVY_CUTOFF_YEN.toLocaleString("ja-JP")}円`,
      source: M01_INCOME_LIMIT_SOURCE,
    },
    amountFormula: {
      annualYenPerRecipient,
      count,
      annualWan,
      fullReliefWan: (annualYenPerRecipient * count) / 10000,
      medicalCostBurdenWan: eligible ? 0 : (annualYenPerRecipient * count) / 10000,
      formula: `${annualYenPerRecipient.toLocaleString("ja-JP")}円 × ${count}人`,
      source: CALCULATION_SOURCES.medicalRepresentative,
    },
    confidence: "representative",
  };
}

function normalizeScenario(scenario) {
  const s = String(scenario || "s2");
  if (s === "S1_R6") return "s1";
  if (s === "S2_R7") return "s2";
  if (s === "S3_R8_R9") return "s3";
  if (s === "S4_R8_FINAL") return "s4";
  return ["s1", "s2", "s3", "s4"].includes(s) ? s : "s2";
}

function toNumber(v, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function roundWan(v, digits = 4) {
  const m = 10 ** digits;
  return Math.round(toNumber(v, 0) * m) / m;
}

function compactDeductions(items) {
  return (Array.isArray(items) ? items : [])
    .map((item) => ({ ...item, wan: roundWan(item?.wan, 4) }))
    .filter((item) => Boolean(item?.alwaysShow) || Math.abs(toNumber(item?.wan, 0)) > 1e-9)
    .map(({ alwaysShow, ...item }) => item);
}

function clampRatio(value, min, max) {
  return Math.max(min, Math.min(max, Number(value)));
}

function computeOptimalModel(series, household, parameters = DEFAULT_OPTIMAL_MODEL) {
  const referenceN04 = series[0]?.breakdown?.programs?.n04 || {};
  const disabilityNeedAnnualWan =
    Number(referenceN04.need?.disabilityAdditionYen || 0) * 12 / 10000;
  const careNeedCount = (household?.children || [])
    .filter((child) => Boolean(child.childWelfareAllowance)).length;
  const careNeedAnnualWan =
    careNeedCount * parameters.careNeedMonthlyYen * 12 / 10000;
  const additionalNeedAnnualWan =
    disabilityNeedAnnualWan + careNeedAnnualWan;
  const currentNeedAnnualWan =
    Number(referenceN04.judgment?.monthlyNeedYen || 0) * 12 / 10000;
  const baseNeedAnnualWan =
    currentNeedAnnualWan - disabilityNeedAnnualWan;
  const needAnnualWan =
    baseNeedAnnualWan + additionalNeedAnnualWan;
  const baseSupportWan =
    parameters.supportMultiplier * additionalNeedAnnualWan;
  const maxCurrentBurdenWan = Math.max(
    ...series.map((point) => {
      const disposable = point.breakdown?.disposable || {};
      return (
        Number(disposable.medicalCostBurdenWan || 0) +
        Number(disposable.serviceFeeWan || 0) +
        Number(disposable.educationCostBurdenWan || 0)
      );
    })
  );
  const maxExistingExpenseReliefWan = Math.max(
    ...series.map((point) =>
      Number(point.breakdown?.programs?.n04?.educationCostReliefWan || 0)
    )
  );
  const plannedExpenseWan =
    maxCurrentBurdenWan + maxExistingExpenseReliefWan;
  const additionalExpenseWan = 0;
  const eligibleExpenseWan =
    plannedExpenseWan + additionalExpenseWan;
  const rawOptimalSeries = series.map((point) => {
    const programs = point.breakdown?.programs || {};
    const n04 = programs.n04 || {};
    const allowance = point.breakdown?.allowance || {};
    const disposable = point.breakdown?.disposable || {};
    const currentDirectSupportWan =
      Number(allowance.tccaWan || 0) + Number(allowance.welfareAllowanceWan || 0);
    const otherCashSupportWan = Math.max(
      0,
      Number(allowance.totalWan || 0) - currentDirectSupportWan
    );
    const takeHomeWan = Number(point.breakdown?.takeHome?.takeHomeWan || 0);
    const preSupportResourcesWan = takeHomeWan + otherCashSupportWan;
    const supportRatio =
      needAnnualWan > 0 ? preSupportResourcesWan / needAnnualWan : Infinity;
    const supportTransition = Number.isFinite(supportRatio)
      ? clampRatio(
          (supportRatio - parameters.lowerRatio) /
            (parameters.upperRatio - parameters.lowerRatio),
          0,
          1
        )
      : 1;
    const directSupportWan = baseSupportWan * (1 - supportTransition);
    const postSupportResourcesWan = preSupportResourcesWan + directSupportWan;
    const burdenRatio =
      needAnnualWan > 0 ? postSupportResourcesWan / needAnnualWan : Infinity;
    const burdenTransition = Number.isFinite(burdenRatio)
      ? clampRatio(
          (burdenRatio - parameters.lowerRatio) /
            (parameters.upperRatio - parameters.lowerRatio),
          0,
          1
        )
      : 1;
    const burdenCapWan =
      parameters.burdenRate * needAnnualWan * burdenTransition;
    const referenceBalanceWan = directSupportWan - burdenCapWan;
    const existingExpenseReliefWan = Number(n04.educationCostReliefWan || 0);
    const currentBurdenWan =
      Number(disposable.medicalCostBurdenWan || 0) +
      Number(disposable.serviceFeeWan || 0) +
      Number(disposable.educationCostBurdenWan || 0);
    const currentBalanceWan =
      currentDirectSupportWan + existingExpenseReliefWan - currentBurdenWan;
    const modelBurdenWan = Math.min(eligibleExpenseWan, burdenCapWan);
    const rawModelBalanceWan = directSupportWan - modelBurdenWan;
    return {
      x: Number(point.x),
      needAnnualWan,
      baseNeedAnnualWan,
      disabilityNeedAnnualWan,
      careNeedAnnualWan,
      additionalNeedAnnualWan,
      preSupportResourcesWan,
      supportRatio,
      supportTransition,
      directSupportWan,
      postSupportResourcesWan,
      burdenRatio,
      burdenTransition,
      burdenCapWan,
      referenceBalanceWan,
      rawModelBalanceWan,
      currentBalanceWan,
      currentDirectSupportWan,
      otherCashSupportWan,
      existingExpenseReliefWan,
      currentBurdenWan,
      plannedExpenseWan,
      additionalExpenseWan,
      eligibleExpenseWan,
      modelBurdenWan,
      refundWan: Math.max(0, eligibleExpenseWan - modelBurdenWan),
      disposableFloorWan:
        postSupportResourcesWan - burdenCapWan,
      takeHomeWan,
      currentDisposableWan: Number(disposable.disposableWan || 0),
    };
  });
  const optimalSeries = rawOptimalSeries.map((point) => {
    const balanceWan = point.rawModelBalanceWan;
    return {
      ...point,
      balanceWan,
      adjustmentWan: balanceWan - point.currentBalanceWan,
      optimalDisposableWan:
        point.takeHomeWan + point.otherCashSupportWan + balanceWan,
    };
  });

  return {
    ...parameters,
    baseSupportWan,
    baseNeedAnnualWan,
    disabilityNeedAnnualWan,
    careNeedCount,
    careNeedAnnualWan,
    additionalNeedAnnualWan,
    needAnnualWan,
    plannedExpenseWan,
    additionalExpenseWan,
    eligibleExpenseWan,
    series: optimalSeries,
  };
}

function standardStates(point) {
  const rows = [];
  const b = point.details?.benefits;
  const special = b?.specialChildAllowance;
  // 所得停止前の障害要件に該当する児童がいない世帯は対象外。停止後の給付ゼロとは区別。
  if (special && special.status !== "no-qualifying-child") for (const c of special.checks) {
    const role = {claimant:"受給資格者",spouse:"受給資格者の配偶者",obligor:"扶養義務者"}[c.role];
    // 受給者（又はその配偶者）が給与順位の交代で別の親になっても、本人表同士・配偶者表同士を比較する。
    rows.push({system:"N01-1",subject:c.role+":"+c.id,trackAs:c.role==="obligor" ? c.role+":"+c.id : c.role,label:"特別児童扶養手当："+role+"（"+memberLabel(c.id)+"）",
      person:c.id,state:incomeState(typeof c.stopped === "boolean" ? !c.stopped : null)});
  }
  for (const child of b?.welfareChildren ?? []) {
    if (child.reasons.includes("non-income-ineligible")) continue;
    const childId=child.checks.find(c=>c.role==="recipient")?.id;
    if (!childId) continue;
    const multiple=child.checks.filter(c=>c.role==="maintainer").length>1;
    for (const c of child.checks) {
      const kind={recipient:"本人",maintainer:"生計維持者",spouse:"本人の配偶者"}[c.role];
      // 単独の維持者が入れ替わった場合は、その時点の維持者の所得判定を比較する。
      // 両者とも制限内なら変化点ではない。判定が異なる場合のみ、入れ替わった人も出力する。
      const suffix=c.role==="maintainer" && multiple ? ":"+c.id : "";
      rows.push({system:"N01-2",subject:childId+":"+c.role+suffix,label:"障害児福祉手当："+memberLabel(childId)+"の"+kind+
        (suffix ? "（"+memberLabel(c.id)+"）" : ""),person:c.id,state:incomeState(c.passes)});
    }
  }
  const service=point.details?.service;
  if (service?.hasCapApplicableServiceUse) {
    const state=({0:"非課税等（上限0円）",4600:"一般1（上限4,600円）",37200:"一般2（上限37,200円）"})[service.householdCapYen] ?? null;
    rows.push({system:"N02/N03",subject:"household",label:"障害福祉サービス・障害児通所支援：世帯の負担上限区分",state});
  }
  return rows;
}

function appendGap(ranges,atWan,metadata={}) {
  const last=ranges[ranges.length-1];
  if (last && last.toWan+1===atWan) last.toWan=atWan;
  else ranges.push({...metadata,fromWan:atWan,toWan:atWan});
}

function scanPaperChangePoints(calculator,axis,fixedWan,{assessors=[],minWan=0,maxWan=MAX_WAN}={}) {
  if (!calculator || typeof calculator.evaluate!=="function" || !["head","spouse"].includes(axis)) throw new TypeError("給与軸と計算器を指定してください。");
  if (![fixedWan,minWan,maxWan].every(v=>Number.isSafeInteger(v)&&v>=0&&v<=MAX_WAN) || minWan>maxWan)
    throw new RangeError("給与は0～1,500万円の整数、走査は昇順で指定してください。");
  if (!Array.isArray(assessors)) throw new TypeError("外部判定器は配列で指定してください。");
  const ids=new Set();
  for (const a of assessors) {
    const subject=a?.subject ?? "household", id=a?.id, key=JSON.stringify([id,subject]);
    if (!a || typeof id!=="string" || !id.trim() || standardSystems.has(id) || ids.has(key) || typeof subject!=="string" || !subject.trim() ||
        typeof a.label!=="string" || !a.label.trim() || typeof a.assess!=="function")
      throw new TypeError("外部判定器には固有の制度ID・対象者の組、表示名、判定関数が必要です。");
    ids.add(key);
  }
  let previous=new Map();
  const events=[],pointGaps=[],unknownByKey=new Map();
  for (let w=minWan;w<=maxWan;w++) {
    const headWan=axis==="head"?w:fixedWan, spouseWan=axis==="spouse"?w:fixedWan;
    const point=headWan===0 && spouseWan===0 ? null : calculator.evaluate(headWan,spouseWan);
    if (point?.status!=="calculated") {
      appendGap(pointGaps,w);
      previous=new Map();
      continue;
    }
    const rows=standardStates(point);
    for (const a of assessors) {
      const state=a.assess(point,{headWan,spouseWan});
      if (state!==null && (typeof state!=="string" || !state.trim())) throw new TypeError(a.id+"は判定区分名またはnullを返してください。");
      rows.push({system:a.id,subject:a.subject ?? "household",label:a.label,state});
    }
    const current=new Map();
    for (const row of rows) {
      const {system,subject,label,state}=row;
      const key=JSON.stringify([system,row.trackAs ?? subject]);
      if (state===null) {
        if (!unknownByKey.has(key)) unknownByKey.set(key,[]);
        appendGap(unknownByKey.get(key),w,{system,subject});
        continue;
      }
      current.set(key,row);
      const prev=previous.get(key);
      if (prev && prev.state!==state) events.push({fromWan:w-1,atWan:w,system,subject,label,before:prev.state,after:state,
        ...(row.person ? {beforePerson:prev.person,afterPerson:row.person} : {})});
    }
    previous=current;
  }
  return {axis,fixedWan,events,unknownRanges:[...unknownByKey.values()].flat(),pointGaps};
}

function paperComparisonInputs(family, fee, protocol="paper-2029") {
  if (!["paper-2029","v3","legacy-v2"].includes(protocol)) throw new RangeError("図表に用いる計算条件が不正です。");
  const children = family.children.map(c=>protocol==="paper-2029" ? {...c} : {...c,taxDependentOf:"head",maintainedByRecipient:false});
  const base = {protocol,children,serviceAmountYen:fee,otherServiceMonthlyYen:0};
  if (protocol==="legacy-v2") return base;
  if (protocol==="paper-2029") return {...base,roles:{spouseDeductionClaimant:"head",allowanceRecipient:"highest-salary",welfareMaintainer:"highest-salary"}};
  return {...base,roles:{spouseDeductionClaimant:"head",allowanceRecipient:"head"},insurance:{
    residence:"funabashi",head:{mode:"contract",workPattern:"regular",workRegion:"chiba"},
    spouse:{mode:"contract",workPattern:"under20",workRegion:"chiba"},
    nationalEstimate:{confirmed:true,payer:"head",children:children.map(c=>({age:c.age,national:false}))},
  }};
}

function analyzePaperSlice(family, spouse, fee, protocol="paper-2029") {
  const calculator = createRevisionCalculator(paperComparisonInputs(family,fee,protocol));
  const points = Array.from({length:1501}, (_, wage) => calculator.evaluate(wage, spouse));
  const {values, falls} = classifyRevisionFalls(points);
  const events = falls.map(({at, delta, recovered, causes, recoveryStatus}) => {
    const service = points[at].details.service;
    const labels = causes.map(cause => cause.startsWith("障害福祉サービス") ?
      (service.householdCapYen === 37200 ? "通所負担（一般1→一般2）" : "通所負担（非課税→一般1）") : cause);
    return {at, lossYen:Math.round(delta*10000), recovered,
      width:recovered === null ? null : recovered-at, recoveryStatus:recoveryStatus ?? (recovered==null ? "beyond-range":"observed"),labels};
  });
  const serviceSteps = [];
  for (let i=1; i<points.length; i++) {
    if (Number.isFinite(values[i-1]) && Number.isFinite(values[i]) &&
        points[i-1].details.service.householdCapYen === 4600 && points[i].details.service.householdCapYen === 37200) {
      serviceSteps.push({at:i, changeYen:Math.round((values[i]-values[i-1])*10000)});
    }
  }
  const gaps=[];
  for(let i=0;i<values.length;i++) if (!Number.isFinite(values[i])) {
    if(i===0 || Number.isFinite(values[i-1])) gaps.push({from:i,to:i,reasons:[]});
    const gap=gaps[gaps.length-1];
    gap.to=i;
    (points[i].reasons??[]).forEach(reason=>{if(!gap.reasons.includes(reason)) gap.reasons.push(reason);});
  }
  return {protocol,id:family.id,spouse,fee,values,events,serviceSteps,gaps,calculatedCount:values.filter(Number.isFinite).length};
}

function assessPaperEducationClass(measurement) {
  if (measurement?.scope !== PAPER_EDUCATION_ASSESSMENT_BASIS.scope) return null;
  const {measuredMonthlyIncomeYen: income, measuredMonthlyNeedYen: need} = measurement;
  if (!Number.isFinite(income) || income < 0 || !Number.isFinite(need) || need <= 0) return null;
  // 倍率を表示用に丸めずに比較する。1.5倍に一致なら第2、2.5倍に一致なら第3。
  return income < need * 1.5 ? "第1区分" : income < need * 2.5 ? "第2区分" : "第3区分";
}

function createPaperEducationAssessor(readMeasurement) {
  if (readMeasurement !== undefined && typeof readMeasurement !== "function") throw new TypeError("N04の測定資料を取得する関数を指定してください。");
  return {
    id:"N04", label:"特別支援教育就学奨励費：特別支援学校小学部の支弁区分（考察用）",
    assess:(point, coordinates)=>point?.status === "calculated" && readMeasurement
      ? assessPaperEducationClass(readMeasurement(point,coordinates)) : null,
  };
}

function severeMedicalStatus(p) {
  if (p.funabashiRegistered===false || p.insured===false || p.publicAssistance===true || p.m01DisabilityConfirmed===false) return "対象外";
  if (p.funabashiRegistered!==true || p.insured!==true || p.publicAssistance!==false || p.m01DisabilityConfirmed!==true) return null;
  const levy=p.adjustedInsuranceUnitLevyYen;
  if (levy==null) return null;
  if (levy<thresholdYen) return "対象";
  if (p.m01ExceptionConfirmed===true) return "対象（特例）";
  if (p.m01ExceptionConfirmed===false) return "対象外（所得制限）";
  return null;
}

function childAgeEligible(p) {
  if (p.ageAtVisit==null) return null;
  if (p.ageAtVisit<18) return true;
  return p.ageAtVisit===18 ? p.withinEndOfFiscalYearAt18 ?? null : false;
}

function childMedicalStatus(p) {
  const age=childAgeEligible(p);
  if (p.funabashiRegistered===false || p.insured===false || p.publicAssistance===true || age===false) return "対象外";
  if (p.claimKind && p.claimKind!=="ordinary-insured") return "対象外（当該費用）";
  if (p.funabashiRegistered!==true || p.insured!==true || p.publicAssistance!==false || age!==true || !p.claimKind) return null;
  return "対象";
}

function childCopayClass(p) {
  if (p.visitType==="pharmacy" || p.childHouseholdLevyTaxable===false) return "無料区分";
  const freeAfter=p.visitType==="outpatient"?6:p.visitType==="inpatient"?11:null;
  if (freeAfter==null || p.ordinalAtSameProviderInMonth==null) return null;
  if (p.ordinalAtSameProviderInMonth>=freeAfter) return "無料区分";
  return p.childHouseholdLevyTaxable===true ? "一部負担区分" : null;
}

function assessFunabashiMedicalCoverage(p={}) {
  if (!p || typeof p!=="object" || Array.isArray(p)) throw new TypeError("医療費助成の判定条件を指定してください。");
  for (const key of ["funabashiRegistered","insured","publicAssistance","withinEndOfFiscalYearAt18","m01DisabilityConfirmed",
    "m01ExceptionConfirmed","otherPriorPublicAid","childHouseholdLevyTaxable"]) {
    if (p[key]!=null && typeof p[key]!=="boolean") throw new TypeError(key+"は真偽値または未確認です。");
  }
  for (const [key,min,max] of [["ageAtVisit",0,19],["adjustedInsuranceUnitLevyYen",0,Number.MAX_SAFE_INTEGER],
    ["ordinalAtSameProviderInMonth",1,Number.MAX_SAFE_INTEGER]]) {
    if (p[key]!=null && (!Number.isSafeInteger(p[key]) || p[key]<min || p[key]>max)) throw new RangeError(key+"の範囲外です。");
  }
  if (p.claimKind!=null && !claimKinds.includes(p.claimKind)) throw new TypeError("未定義の費目区分です。");
  if (p.visitType!=null && !["outpatient","inpatient","pharmacy"].includes(p.visitType)) throw new TypeError("未定義の診療区分です。");
  const m01Status=severeMedicalStatus(p),childStatus=childMedicalStatus(p);
  let coordination=null;
  if (childStatus==="対象") {
    if (p.otherPriorPublicAid===true) coordination="他公費優先。残る自己負担は子ども医療で調整しうる";
    else if (p.otherPriorPublicAid===false && m01Status!==null) coordination=m01Status.startsWith("対象外")
      ? "M01対象外・子ども医療は対象" : "両制度の要件に該当（重複計上しない）";
  } else if (childStatus!==null) coordination="子ども医療による代替の対象外";
  return {m01Status,childStatus,childCopayClass:childStatus==="対象"?childCopayClass(p):null,coordination};
}

function funabashiMedicalBoundaryExample() {
  return [234900,235000].map(adjustedInsuranceUnitLevyYen=>({adjustedInsuranceUnitLevyYen,
    ...assessFunabashiMedicalCoverage({...standardFunabashiChildVisit,adjustedInsuranceUnitLevyYen})}));
}

function beforeAdjustmentYen(salaryYen) {
  if (salaryYen < 691000) return 0;
  if (salaryYen < 2026000) return salaryYen - 690000;
  if (salaryYen < 2028000) return 1336000;
  if (salaryYen < 2032000) return 1338000;
  if (salaryYen < 2036000) return 1342000;
  if (salaryYen < 3600000) return Math.floor(salaryYen / 4000) * 2800 - 80000;
  if (salaryYen < 6600000) return Math.floor(salaryYen / 4000) * 3200 - 440000;
  if (salaryYen < 8500000) return Math.floor(salaryYen * 9 / 10) - 1100000;
  return salaryYen - 1950000;
}

function basicIncomeTaxDeduction2029Yen(totalIncomeYen) {
  if (!Number.isSafeInteger(totalIncomeYen) || totalIncomeYen < 0) {
    throw new RangeError("合計所得金額は0以上の整数円で指定してください。");
  }
  if (totalIncomeYen <= 1320000) return 990000;
  if (totalIncomeYen <= 23500000) return 620000;
  if (totalIncomeYen <= 24000000) return 480000;
  if (totalIncomeYen <= 24500000) return 320000;
  if (totalIncomeYen <= 25000000) return 160000;
  return 0;
}

function calculatePaperSalaryTaxInputs2029({ annualSalaryYen, eligibleForIncomeAdjustment } = {}) {
  if (!Number.isSafeInteger(annualSalaryYen) || annualSalaryYen < 0 || annualSalaryYen > 15000000 ||
      typeof eligibleForIncomeAdjustment !== "boolean") {
    throw new RangeError("給与は0～1,500万円の整数円、所得金額調整控除の該当は真偽値で指定してください。");
  }
  const salaryIncomeBeforeAdjustmentYen = beforeAdjustmentYen(annualSalaryYen);
  const incomeAdjustmentDeductionYen = childOrDisabilityIncomeAdjustmentYen(annualSalaryYen, eligibleForIncomeAdjustment);
  const salaryIncomeYen = salaryIncomeBeforeAdjustmentYen - incomeAdjustmentDeductionYen;
  return {
    policyId: PAPER_SALARY_POLICY_2029.id, annualSalaryYen, salaryIncomeBeforeAdjustmentYen,
    incomeAdjustmentDeductionYen, salaryIncomeYen,
    basicIncomeTaxDeductionYen: basicIncomeTaxDeduction2029Yen(salaryIncomeYen),
  };
}

function coverageStatus(role, plan, wages) {
  const mode = plan[role]?.mode, partner = opposite(role);
  if (mode === "employee") return wages[role] > 0
    ? {status:"employee"} : {status:"undetermined", issue:"給与0円時の本人加入・休業等をこの勤務ケースでは算定しません。"};
  if (mode !== "outside") return {status:"undetermined", issue:plan[role]?.reason || "この給与点に適用できる勤務先の加入条件が未確定です。"};
  if (wages[role] >= 130 || plan[partner]?.mode === "outside") return {status:"national"};
  if (plan[partner]?.mode !== "employee" || wages[partner] === 0)
    return {status:"undetermined", issue:"扶養する側の職場保険加入を確認できません。"};
  if (2 * wages[role] < wages[partner]) return {status:"dependent"};
  if (wages[role] <= wages[partner])
    return {status:"undetermined", issue:"給与見込が扶養者の2分の1以上で、個別の生計維持認定が必要です。"};
  return {status:"national"};
}

function regionalNational(plan, fiscalYear, wages, states) {
  const assumptions = plan.nationalEstimate;
  const nationalRoles = roles.filter(role=>states[role].status === "national");
  /** 資料不足を0円に置かず、その理由を返す。 */
  const fail = message=>({known:false,reasons:[message]});
  if (roles.some(role=>states[role].status === "undetermined"))
    return fail("夫婦の国保加入者を確定できず、船橋市の国保料を推計できません。");
  let children = assumptions.children;
  if (assumptions.childrenMode === "follow-parents") {
    // 給与のみ・前年から同額という研究仮定の下で、混合加入時も見込年収を比較する。
    // 同額時の生計維持認定は推測しない。税扶養・特児受給者からは導出しない。
    const employee = roles.find(role=>states[role].status === "employee");
    const national = nationalRoles[0];
    if (nationalRoles.length === 1 && employee && wages[national] === wages[employee])
      return fail("被用者保険と国保の親の見込年収が同額のため、子どもの生計維持認定を確認する必要があります。");
    const inNational = nationalRoles.length === 2 || (nationalRoles.length === 1 && employee && wages[national] > wages[employee]);
    children = Array.isArray(children) ? children.map(c=>({...c,national:Boolean(inNational)})) : children;
  }
  if (!Array.isArray(children) || !children.length ||
      children.some(c=>!c || !Number.isInteger(c.age) || c.age<0 || c.age>17 || typeof c.national !== "boolean"))
    return fail("船橋市の国保に加入する子どもと年齢区分を確認してください。");
  if (nationalRoles.length === 2 && children.some(c=>!c.national))
    return fail("両親とも国保の給与点です。他の保険がない前提では、同居する子どもも国保の加入者に指定してください。");
  if (!nationalRoles.length) {
    if (children.some(c=>c.national))
      return fail("今回の世帯条件では、国保の親がいない給与点で子どもだけの国保加入は想定していません。");
    return null;
  }
  return estimateFunabashiNational({fiscalYear,headWan:wages.head,spouseWan:wages.spouse,
    nationalRoles,children,payer:assumptions.payer,standardPension:true});
}

function calculateHouseholdCoverage(insurance, headWan, spouseWan) {
  if (![headWan,spouseWan].every(w => Number.isSafeInteger(w) && w >= 0 && w <= 1500))
    throw new RangeError("社会保険の計算には各人の0～1,500万円の整数給与を指定してください。");
  const plan = insurance ?? {};
  const wages = {head:headWan,spouse:spouseWan};
  const reasons = new Set();
  const measuredHere = plan.measuredAt?.headWan === headWan && plan.measuredAt?.spouseWan === spouseWan;
  const health = plan.nationalHealth;
  const regionalRequested = plan.residence === "funabashi" && plan.nationalEstimate?.confirmed === true;
  const regionalEstimates = {current:null,previous:null};
  const result = Object.fromEntries(roles.map(role=>[role,{status:null,previousStatus:null,social:null,prevSocial:null,current:null,previous:null}]));
  for (const [key,year,field,socialKey] of [
    ["current",2026,"currentNationalYen","social"],["previous",2025,"previousNationalYen","prevSocial"],
  ]) {
    const current = key === "current", period = current ? "当年" : "前年";
    const plans = Object.fromEntries(roles.map(role=>{
      const profile = plan[role] ?? {};
      // 国保の住所から協会けんぽ支部を逆算しない。職域加入の保険料・就労地域別最低賃金は
      // 調査した勤務先地域（船橋＝千葉支部、東京支部）を明示したときだけ使う。
      if (wages[role] > 0 && (profile.mode === "employee" || profile.mode === "contract") &&
          !["chiba","tokyo"].includes(profile.workRegion))
        return [role,{...profile,mode:"unknown",reason:"勤務先の地域（協会けんぽの支部）が未指定・対象外です。"}];
      return [role, profile.mode === "contract" ? {...profile,...resolveEmploymentContract(profile,wages[role],year)} : profile];
    }));
    const states = Object.fromEntries(roles.map(role => [role,coverageStatus(role,plans,wages)]));
    const nationalRoles = roles.filter(role => states[role].status === "national");
    const nationalCount = nationalRoles.length;
    const declared = measuredHere && nationalCount > 0 && (
      nationalRoles.some(role=>plans[role][field]!=null) || health?.[current ? "currentYen" : "previousYen"] != null
    );
    const regional = regionalRequested && !declared ? regionalNational(plan,year,wages,states) : null;
    regionalEstimates[key] = regional;
    const householdAmountRequired = nationalCount > 1 || (nationalCount > 0 && health != null);
    const invalidShared = !regional && householdAmountRequired && (!health || !roles.includes(health.payer));
    if (invalidShared) reasons.add(period + "の国保世帯分の実際の支払者と世帯保険料を一組だけ入力してください。");
    for (const role of roles) {
      const out = result[role], person = plans[role], state = states[role];
      out[current ? "status" : "previousStatus"] = state.status;
      if (state.issue) reasons.add(names[role] + "（" + period + "）：" + state.issue);
      if (state.status === "undetermined") continue;
      if (regional && !regional.known) {
        regional.reasons.forEach(message=>reasons.add(period + "：" + message));
        continue;
      }
      if (typeof person.employmentInsurance !== "boolean" && wages[role] > 0) {
        reasons.add(names[role] + "：雇用保険の加入条件が未設定です。");
        continue;
      }
      // 賞与なし・均等な月給とし、東京の各年度の標準報酬等級から12か月を算定する。
      // 雇用保険は加入時のみ別経路で足す。給与ゼロは雇用保険だけが必ずゼロ。
      const payroll = state.status === "employee" ? annualEmployeePremiums(wages[role],year,person.employmentInsurance,person.healthBranch ?? person.workRegion) : null;
      const employmentYen = payroll ? payroll.employmentYen : person.employmentInsurance ? annualEmploymentPremium(wages[role],year) : 0;
      const workplaceYen = payroll ? payroll.totalYen - payroll.employmentYen : 0;
      let nationalYen = 0, familyHealthYen = 0;
      if (regional) {
        nationalYen = regional.pensionYen[role] ?? 0;
        if (plan.nationalEstimate.payer === role) familyHealthYen = regional.healthYen;
      } else if (state.status === "national") {
        if (!measuredHere || !isAmount(person[field]) || invalidShared) {
          reasons.add(names[role] + "：" + period + "のこの給与点での国保・国民年金の支払額を確認できません。");
          continue;
        }
        nationalYen = person[field];
      }
      if (!regional && householdAmountRequired && !invalidShared && health.payer === role) {
        const amount = health[current ? "currentYen" : "previousYen"];
        if (!measuredHere || !isAmount(amount)) {
          reasons.add(period + "のこの給与点での国保世帯分の支払額が未設定です。");
          continue;
        }
        familyHealthYen = amount;
      }
      const sum = workplaceYen + employmentYen + nationalYen + familyHealthYen;
      if (!Number.isSafeInteger(sum)) throw new RangeError("保険料の入力額が大きすぎます。");
      out[key] = {workplaceYen, employmentYen, nationalYen, householdHealthYen:familyHealthYen,
        nationalMethod:regional ? "funabashi-estimate" : nationalCount ? "entered" : "not-applicable",payroll,totalYen:sum};
      out[socialKey] = sum;
    }
  }
  const currentKnown = roles.every(role=>result[role].social !== null);
  const previousKnown = roles.every(role=>result[role].prevSocial !== null);
  return {...result, known:currentKnown && previousKnown, currentKnown, previousKnown, regionalEstimates, reasons:[...reasons]};
}

function requireInteger(value, min, max, label) {
  if (!Number.isSafeInteger(value) || value < min || value > max) throw new RangeError(label + "が設定範囲外です。");
  return value;
}

function validateRevisionHousehold(input) {
  if (!input || !Array.isArray(input.children) || input.children.length < 1 || input.children.length > 3) throw new RangeError("子どもは1～3人を指定してください。");
  const protocol = input.protocol ?? "v3";
  if (!["paper-2029","v3","legacy-v2"].includes(protocol)) throw new RangeError("算定仕様が不明です。");
  const paper = protocol === "paper-2029";
  const requestedRecipient = input.roles?.allowanceRecipient ?? (paper ? "highest-salary" : "head");
  if (!(paper ? ["head","spouse","highest-salary"] : ["head","spouse"]).includes(requestedRecipient)) throw new RangeError("受給資格者の指定が不正です。");
  const roles = {
    spouseDeductionClaimant:input.roles?.spouseDeductionClaimant ?? "head",
    allowanceRecipient:paper ? "highest-salary" : requestedRecipient,
    welfareMaintainer:input.roles?.welfareMaintainer ?? (protocol === "paper-2029" ? "highest-salary" : "both"),
  };
  if (!["head","spouse","none"].includes(roles.spouseDeductionClaimant)) throw new RangeError("配偶者控除の申告者の指定が不正です。");
  if (!(protocol === "paper-2029" ? ["head","spouse","highest-salary"] : ["head","spouse","highest-salary","both"]).includes(roles.welfareMaintainer))
    throw new RangeError("障害児福祉手当の生計維持者の仮定が不正です。");
  if (protocol === "paper-2029" && input.insurance !== undefined)
    throw new RangeError("2029年末の比較には旧版の勤務条件・国保入力を持ち込めません。");
  const serviceAmountYen = requireInteger(input.serviceAmountYen, 0, MAX_SERVICE_YEN, "利用額");
  const otherServiceMonthlyYen = requireInteger(input.otherServiceMonthlyYen ?? 0, 0, MAX_SERVICE_YEN, "同じ保護者に係るその他の合算対象負担");
  const children = input.children.map((c, i) => {
    const age = requireInteger(c?.age, 0, 17, "子どもの年齢");
    if (!["not","2","1"].includes(c.tccaGrade) || !["none","ordinary","special"].includes(c.taxStatus) ||
        typeof c.welfareEligible !== "boolean" || typeof c.serviceUser !== "boolean") throw new RangeError("子ども" + (i+1) + "の制度別条件が未指定です。");
    if (c.welfareEligible && c.tccaGrade === "not") throw new RangeError("法第2条第2項の重度障害児は同条第1項の障害児に含まれます。所得停止前の特児の障害等級を指定してください。");
    const individual = requireInteger(c.serviceAmountYen ?? serviceAmountYen, 0, MAX_SERVICE_YEN, "児童別利用額");
    const record = { age, tccaGrade:c.tccaGrade, taxStatus:c.taxStatus, welfareEligible:c.welfareEligible, serviceUser:c.serviceUser, serviceAmountYen:individual };
    // 論文用は各給与点で全児童の税扶養先を定める。旧画面の固定扶養先・追加申告は引き継がない。
    if (paper) return record;
    const taxDependentOf = c.taxDependentOf ?? "head", maintainedByRecipient = c.maintainedByRecipient ?? false;
    if (!["head","spouse"].includes(taxDependentOf) || typeof maintainedByRecipient !== "boolean") throw new RangeError("児童の扶養関係の指定が不正です。");
    return {...record, taxDependentOf, maintainedByRecipient};
  });
  const insurance = input.insurance?.nationalEstimate?.childrenMode === "follow-parents" ? {
    ...input.insurance, nationalEstimate:{...input.insurance.nationalEstimate,children:children.map(c=>({age:c.age}))},
  } : input.insurance;
  return { children, otherServiceMonthlyYen, roles, protocol, insurance };
}

function revisionSalaryRecord(salaryWan, steady2029=false) {
  const salaryYen = salaryWan*WAN;
  if (steady2029) {
    const s = calculatePaperSalaryTaxInputs2029({annualSalaryYen:salaryYen, eligibleForIncomeAdjustment:true});
    // 前年から昇給なし、同一の制度・料率を12か月続けた静学比較。過年度の天引き実績ではない。
    return {salaryYen, income:s.salaryIncomeYen, prevIncome:s.salaryIncomeYen,
      prevGrossIncome:s.salaryIncomeBeforeAdjustmentYen, steady2029, salaryTaxInputs:s};
  }
  // 所得金額調整控除は扶養控除の一人限定とは異なり、23歳未満の子がいれば両親とも適用可能。
  const adjustment = childOrDisabilityIncomeAdjustmentYen(salaryYen, true);
  // 既存の比較シナリオでは両年に同額の給与を渡す。個人の給与所得計算自体は暦年別。
  const prevGrossIncome = salaryIncomeBeforeAdjustmentYen(salaryYen, 2025);
  return {
    salaryYen, income:salaryIncomeBeforeAdjustmentYen(salaryYen, 2026)-adjustment,
    prevIncome:prevGrossIncome-adjustment, prevGrossIncome,
  };
}

function archivedPremiums(salaryWan) {
  return {social:Math.round(calculateSocialInsuranceComponents(salaryWan,AGE_OF_PARENTS,"s4").totalWan*WAN),
    prevSocial:Math.round(calculateSocialInsuranceComponents(salaryWan,AGE_OF_PARENTS,"s2").totalWan*WAN)};
}

function revisionSpouseDeduction(own, partner, ordinaryLimit) {
  const band = own <= 9000000 ? 0 : own <= 9500000 ? 1 : own <= 10000000 ? 2 : -1;
  const row = REVISION_SPOUSE_DEDUCTION_TABLE.find(entry => partner <= entry[0] * WAN);
  if (band < 0 || !row) return {kind:"none", it:0, lt:0, specialLT:0, difference:0};
  const it = row[1][band]*WAN, lt = row[2][band]*WAN;
  const ordinary = partner <= ordinaryLimit;
  return {kind:ordinary ? "ordinary" : "special", it, lt, specialLT:ordinary ? 0 : lt, difference:ordinary ? it-lt : 0};
}

function revisionParentTax(person, partner, dependents, claimsSpouse, archived) {
  const older = dependents.filter(c => c.age >= 16).length;
  const ordinary = dependents.filter(c => c.taxStatus === "ordinary").length;
  const special = dependents.filter(c => c.taxStatus === "special").length;
  const childIT = (older*38 + ordinary*27 + special*75)*WAN;
  const childLT = (older*33 + ordinary*26 + special*53)*WAN;
  const spouse = revisionSpouseDeduction(person.income, claimsSpouse ? partner.income : Infinity, 620000);
  const previousOrdinaryLimit = person.steady2029 ? 620000 : 580000;
  const prevSpouse = revisionSpouseDeduction(person.prevIncome, claimsSpouse ? partner.prevIncome : Infinity, previousOrdinaryLimit);
  // 「同一生計配偶者」の有無は、配偶者控除額そのものではない。本研究は夫婦同居・同一生計・給与のみ。
  const familySpouse = (!archived || claimsSpouse) && partner.income <= 620000;
  const prevFamilySpouse = (!archived || claimsSpouse) && partner.prevIncome <= previousOrdinaryLimit;
  // 所得・控除を整数円で差し引いてから税計算器に渡す。万円単位での減算は境界で
  // 999.999…円を作り、課税所得の千円未満切捨てが一段ずれることがある。
  const basicITYen = person.steady2029 ? person.salaryTaxInputs.basicIncomeTaxDeductionYen : calcBasicIncomeTaxDeductionR8FinalWan(person.income/WAN)*WAN;
  const itBase = person.income-person.social-childIT-spouse.it-basicITYen;
  const it = getIncomeTaxParts(itBase/WAN, {includeReconstruction:true, includeDefense:person.steady2029===true});
  const resident = getResidentTaxParts((person.income-person.social-childLT-spouse.lt-430000)/WAN, {
    totalIncomeWan:person.income/WAN, dependentCount:dependents.length + Number(familySpouse),
    applySalaryOnlyExemptionAdjustment:person.steady2029 === true,
    personalDeductionDifferenceWan:5+(childIT-childLT+spouse.difference)/WAN,
  });
  const prevResident = getResidentTaxParts((person.prevIncome-person.prevSocial-childLT-prevSpouse.lt-430000)/WAN, {
    totalIncomeWan:person.prevIncome/WAN, dependentCount:dependents.length + Number(prevFamilySpouse),
    applySalaryOnlyExemptionAdjustment:person.steady2029 === true,
    personalDeductionDifferenceWan:5+(childIT-childLT+prevSpouse.difference)/WAN,
  });
  return {
    currentIncomeYen:person.income, previousIncomeYen:person.prevIncome, socialYen:person.social, previousSocialYen:person.prevSocial,
    ...(person.steady2029 ? {salaryTaxInputs:person.salaryTaxInputs, basicITYen, nationalTax:it, residentTax:resident} : {}),
    spouseDeduction:{current:spouse, previous:prevSpouse}, taxDependentCount:dependents.length, olderDependentCount:older,
    totalTaxYen:it.taxYen+Math.round(resident.totalWan*WAN), incomeTaxYen:it.taxYen, residentTaxYen:Math.round(resident.totalWan*WAN),
    forestTaxYen:resident.forestEnvironmentTaxYen, spouseDeductionITYen:spouse.it, disabilityDeductionITYen:(ordinary*27+special*75)*WAN,
    serviceLevyYen:calcServiceAssessmentLevyYen(prevResident.municipalIncomeLevyYen, dependents.map(c => c.age)),
    serviceTaxable:prevResident.perCapitaYen > 0 || prevResident.incomeLevyYen > 0,
    // 施行令第5条の給与所得（所得税法28条2項）から給与10万円・一律8万円等。税の同居特障75万は使わない。
    allowanceIncomeYen:salaryOnlySpecialChildIncome({salaryIncomeBeforeAdjustmentYen:person.prevGrossIncome,
      spouseSpecialDeductionYen:prevSpouse.specialLT,ordinaryDisabilityCount:ordinary,specialDisabilityCount:special}),
    welfareMaintainerIncomeYen:calculateWelfareSalaryAssessment({role:"maintainer", salaryIncomeYen:person.prevGrossIncome,
      ordinaryDisabledDependents:ordinary,specialDisabledDependents:special,otherAllowedDeductionsYen:prevSpouse.specialLT}).incomeYen,
    allowanceFuyo:dependents.length + Number(prevFamilySpouse),
  };
}

function revisionCashBenefits(children, claimant, other, additionalSupportedCount, claimantId, maintainerId) {
  const spouseId = claimantId === "head" ? "spouse" : "head";
  const specialChildAllowance = calculateSpecialChildAllowance({
    grades:children.map(c=>c.tccaGrade),
    claimant:{id:claimantId,assessmentIncomeYen:claimant.allowanceIncomeYen,dependentCount:claimant.allowanceFuyo},
    spouse:{id:spouseId,assessmentIncomeYen:other.allowanceIncomeYen,dependentCount:other.allowanceFuyo},
    // 同一生計の直系血族である子もここでは無所得・扶養親族なし。別居の祖父母等は想定しない。
    otherObligors:children.map((_,i)=>({id:"child"+(i+1),assessmentIncomeYen:0,dependentCount:0})),
    additionalMaintainedChildren:additionalSupportedCount, claimantOlderTaxDependents:claimant.olderDependentCount,
  });
  const limit = specialChildAllowance.checks[0].limitYen;
  const obligorLimit = calcWelfareAllowanceLimitObligorYen(claimant.allowanceFuyo);
  const otherLimit = calcWelfareAllowanceLimitObligorYen(other.allowanceFuyo);
  const tccaOK = specialChildAllowance.incomeEligible;
  // 障害児福祉手当の本人所得は0。本人の上限超と、両親の上限以上停止は同じ判定ではない。
  const tcca = specialChildAllowance.annualYen;
  // 特児の配偶者判定を児福に流用しない。児福の受給者は児童本人、その生計を維持する親は別指定。
  const maintainers = [[claimantId,claimant],[spouseId,other]].filter(([id])=>maintainerId==="both" || id===maintainerId)
    .map(([id,tax])=>({id,incomeYen:tax.welfareMaintainerIncomeYen,dependentCount:tax.allowanceFuyo}));
  const welfareChildren = children.map((c,i)=>calculateDisabledChildWelfareAllowance({eligible:c.welfareEligible,
    recipient:{id:"child"+(i+1), incomeYen:0, dependentCount:0}, maintainers}));
  const welfareOK = welfareChildren.every(c=>c.incomeEligible);
  const welfare = welfareChildren.reduce((sum,c)=>sum+c.annualYen,0);
  // 第3子以降は出生順（高年齢順）。年齢でソートしても子どもごとの入力対応は維持される。
  const childAllowance = [...children].sort((a,b)=>b.age-a.age).reduce((s,c,i)=>s+(i>=2 ? 30000 : c.age<3 ? 15000 : 10000),0)*12;
  return {tcca, welfare, childAllowance, specialChildAllowance, welfareChildren, additionalSupportedCount, claimantLimitYen:limit, obligorLimitYen:obligorLimit, otherLimitYen:otherLimit, tccaOK, welfareOK};
}

function revisionServiceBurden(children, otherServiceMonthlyYen, adults) {
  const levy = adults.reduce((sum,t)=>sum+t.serviceLevyYen,0);
  const cap = getChildDayServiceCapYen(levy, adults.some(t=>t.serviceTaxable));
  // 各児入力は多子軽減等を適用した後・上限前。3～5歳は年度当初年齢に基づく無償対象通所のみを仮定。
  const day = children.reduce((sum,c)=>sum + (c.serviceUser && (c.age < 3 || c.age > 5) ? c.serviceAmountYen : 0),0);
  const monthly = Math.min(day+otherServiceMonthlyYen,cap);
  // 就学前無償だけの利用を除く。利用料0円という入力も「利用していない」ことは意味しない。
  const hasCapApplicableServiceUse=otherServiceMonthlyYen>0 || children.some(c=>c.serviceUser && (c.age<3 || c.age>5));
  return {annual:monthly*12, monthly, dayMonthlyBeforeCapYen:day, otherServiceMonthlyYen, householdCapYen:cap,
    assessmentLevyYen:levy, hasCapApplicableServiceUse};
}

function createRevisionCalculator(input) {
  const {children, otherServiceMonthlyYen, protocol, roles, insurance} = validateRevisionHousehold(input);
  const archived = protocol === "legacy-v2";
  const steady2029 = protocol === "paper-2029";
  const wages = new Map();
  /** 一度計算した個人給与の基礎値を二つの軸で共有する。親の扶養・給付の判定値は共有しない。 */
  function wageRecord(w) {
    requireInteger(w,0,MAX_WAGE,"給与収入（万円、1万円刻み）");
    if (!wages.has(w)) wages.set(w, archived ? {...revisionSalaryRecord(w), ...archivedPremiums(w)} : revisionSalaryRecord(w,steady2029));
    return wages.get(w);
  }
  /**
   * 同じ給与点で全制度を評価し、年間収支（万円）と各判定（円）を返す。
   * @param {number} headWan 世帯主の年間給与収入（整数、0～1,500万円）。
   * @param {number} spouseWan 配偶者の年間給与収入（整数、0～1,500万円）。
   * @returns {object} 試算対象制度のみの年間可処分所得（未算定ならnull）、内訳（万円）、判定根拠。
   */
  function evaluate(headWan, spouseWan) {
    const headWage = wageRecord(headWan), spouseWage = wageRecord(spouseWan);
    // 法3条2項の「主として生計を維持する者」を本試算では給与収入の多い親で近似（同額は世帯主）。
    // 論文用では子全員の税扶養・障害者控除も同じ親に帰属させる。配偶者控除の申告者は別設定。
    const higher = headWan >= spouseWan ? "head" : "spouse";
    const recipient = archived || steady2029 ? higher : roles.allowanceRecipient;
    const filing = archived ? higher : roles.spouseDeductionClaimant;
    const taxDependentOf = children.map(c => archived || steady2029 ? higher : c.taxDependentOf);
    const maintainerId = roles.welfareMaintainer === "highest-salary" ? higher : roles.welfareMaintainer;
    const assigned = {allowanceRecipient:recipient, spouseDeductionClaimant:filing, taxDependentOf,
      ...(steady2029 ? {allowanceRecipientAssumption:"highest-salary",welfareMaintainer:maintainerId,welfareMaintainerAssumption:roles.welfareMaintainer} : {})};
    const fixedInsurance = steady2029 ? calculateHouseholdInsurance2029({headAnnualYen:headWage.salaryYen,spouseAnnualYen:spouseWage.salaryYen}) : null;
    if (fixedInsurance?.status === "excluded") return {status:"excluded", protocol, reasons:["夫婦とも給与0円の原点は試算対象外です。"], recipient,
      studyDisposableWan:null, disposableWan:null, breakdown:null, details:{insurance:fixedInsurance,roles:assigned}};
    const coverage = steady2029 ? {known:true, protocol, reasons:[],
      head:{...fixedInsurance.head,social:fixedInsurance.head.annual.totalYen,prevSocial:fixedInsurance.head.annual.totalYen},
      spouse:{...fixedInsurance.spouse,social:fixedInsurance.spouse.annual.totalYen,prevSocial:fixedInsurance.spouse.annual.totalYen}} :
      archived ? {known:true, protocol, head:{social:headWage.social,prevSocial:headWage.prevSocial},
      spouse:{social:spouseWage.social,prevSocial:spouseWage.prevSocial}, reasons:[]} :
      calculateHouseholdCoverage(insurance, headWan, spouseWan);
    if (!coverage.known) return {status:"insufficient", protocol, reasons:coverage.reasons, recipient,
      studyDisposableWan:null, disposableWan:null, breakdown:null, details:{coverage,insurance:coverage,roles:assigned}};
    const head = {...headWage, social:coverage.head.social, prevSocial:coverage.head.prevSocial};
    const spouse = {...spouseWage, social:coverage.spouse.social, prevSocial:coverage.spouse.prevSocial};
    const ht = revisionParentTax(head,spouse,children.filter((_,i)=>taxDependentOf[i] === "head"),filing === "head", archived);
    const st = revisionParentTax(spouse,head,children.filter((_,i)=>taxDependentOf[i] === "spouse"),filing === "spouse", archived);
    // 論文用では全児童が受給資格者の税扶養。税扶養外の維持児童として重複加算しない。
    const additional = steady2029 ? 0 : children.filter((c,i)=>taxDependentOf[i] !== recipient && c.maintainedByRecipient).length;
    if (steady2029) assigned.additionalMaintainedChildren = additional;
    const benefits = revisionCashBenefits(children,recipient === "head" ? ht : st,recipient === "head" ? st : ht, additional, recipient, maintainerId);
    const service = revisionServiceBurden(children,otherServiceMonthlyYen,[ht,st]);
    const salary = head.salaryYen+spouse.salaryYen, tax = ht.totalTaxYen+st.totalTaxYen, social = head.social+spouse.social;
    const disposableWan = (salary-tax-social+benefits.tcca+benefits.welfare+benefits.childAllowance-service.annual)/WAN;
    return {status:"calculated", protocol, reasons:[], studyDisposableWan:disposableWan, disposableWan, recipient,
      breakdown:{ salaryWan:salary/WAN, taxWan:tax/WAN, socialWan:social/WAN, tccaWan:benefits.tcca/WAN,
        welfareWan:benefits.welfare/WAN, childAllowanceWan:benefits.childAllowance/WAN, serviceWan:service.annual/WAN },
      ...(steady2029 ? {basis:{rulesAsOf:"2029-12",salaryTaxPolicy:PAPER_SALARY_POLICY_2029.id,
        insuranceRateProxyFiscalYear:fixedInsurance.policy.proxyRateFiscalYear, indexedAllowanceAmountsAsOf:"2026-04",
        calculation:"年末の制度・固定世帯条件を12か月適用した比較。実際の2029年家計の予測ではない。"}} : {}),
      details:{headTax:ht, spouseTax:st, benefits, service, coverage,insurance:fixedInsurance ?? coverage,roles:assigned}};
  }
  return {evaluate};
}

function wageRecord(w) {
    requireInteger(w,0,MAX_WAGE,"給与収入（万円、1万円刻み）");
    if (!wages.has(w)) wages.set(w, archived ? {...revisionSalaryRecord(w), ...archivedPremiums(w)} : revisionSalaryRecord(w,steady2029));
    return wages.get(w);
  }

function evaluate(headWan, spouseWan) {
    const headWage = wageRecord(headWan), spouseWage = wageRecord(spouseWan);
    // 法3条2項の「主として生計を維持する者」を本試算では給与収入の多い親で近似（同額は世帯主）。
    // 論文用では子全員の税扶養・障害者控除も同じ親に帰属させる。配偶者控除の申告者は別設定。
    const higher = headWan >= spouseWan ? "head" : "spouse";
    const recipient = archived || steady2029 ? higher : roles.allowanceRecipient;
    const filing = archived ? higher : roles.spouseDeductionClaimant;
    const taxDependentOf = children.map(c => archived || steady2029 ? higher : c.taxDependentOf);
    const maintainerId = roles.welfareMaintainer === "highest-salary" ? higher : roles.welfareMaintainer;
    const assigned = {allowanceRecipient:recipient, spouseDeductionClaimant:filing, taxDependentOf,
      ...(steady2029 ? {allowanceRecipientAssumption:"highest-salary",welfareMaintainer:maintainerId,welfareMaintainerAssumption:roles.welfareMaintainer} : {})};
    const fixedInsurance = steady2029 ? calculateHouseholdInsurance2029({headAnnualYen:headWage.salaryYen,spouseAnnualYen:spouseWage.salaryYen}) : null;
    if (fixedInsurance?.status === "excluded") return {status:"excluded", protocol, reasons:["夫婦とも給与0円の原点は試算対象外です。"], recipient,
      studyDisposableWan:null, disposableWan:null, breakdown:null, details:{insurance:fixedInsurance,roles:assigned}};
    const coverage = steady2029 ? {known:true, protocol, reasons:[],
      head:{...fixedInsurance.head,social:fixedInsurance.head.annual.totalYen,prevSocial:fixedInsurance.head.annual.totalYen},
      spouse:{...fixedInsurance.spouse,social:fixedInsurance.spouse.annual.totalYen,prevSocial:fixedInsurance.spouse.annual.totalYen}} :
      archived ? {known:true, protocol, head:{social:headWage.social,prevSocial:headWage.prevSocial},
      spouse:{social:spouseWage.social,prevSocial:spouseWage.prevSocial}, reasons:[]} :
      calculateHouseholdCoverage(insurance, headWan, spouseWan);
    if (!coverage.known) return {status:"insufficient", protocol, reasons:coverage.reasons, recipient,
      studyDisposableWan:null, disposableWan:null, breakdown:null, details:{coverage,insurance:coverage,roles:assigned}};
    const head = {...headWage, social:coverage.head.social, prevSocial:coverage.head.prevSocial};
    const spouse = {...spouseWage, social:coverage.spouse.social, prevSocial:coverage.spouse.prevSocial};
    const ht = revisionParentTax(head,spouse,children.filter((_,i)=>taxDependentOf[i] === "head"),filing === "head", archived);
    const st = revisionParentTax(spouse,head,children.filter((_,i)=>taxDependentOf[i] === "spouse"),filing === "spouse", archived);
    // 論文用では全児童が受給資格者の税扶養。税扶養外の維持児童として重複加算しない。
    const additional = steady2029 ? 0 : children.filter((c,i)=>taxDependentOf[i] !== recipient && c.maintainedByRecipient).length;
    if (steady2029) assigned.additionalMaintainedChildren = additional;
    const benefits = revisionCashBenefits(children,recipient === "head" ? ht : st,recipient === "head" ? st : ht, additional, recipient, maintainerId);
    const service = revisionServiceBurden(children,otherServiceMonthlyYen,[ht,st]);
    const salary = head.salaryYen+spouse.salaryYen, tax = ht.totalTaxYen+st.totalTaxYen, social = head.social+spouse.social;
    const disposableWan = (salary-tax-social+benefits.tcca+benefits.welfare+benefits.childAllowance-service.annual)/WAN;
    return {status:"calculated", protocol, reasons:[], studyDisposableWan:disposableWan, disposableWan, recipient,
      breakdown:{ salaryWan:salary/WAN, taxWan:tax/WAN, socialWan:social/WAN, tccaWan:benefits.tcca/WAN,
        welfareWan:benefits.welfare/WAN, childAllowanceWan:benefits.childAllowance/WAN, serviceWan:service.annual/WAN },
      ...(steady2029 ? {basis:{rulesAsOf:"2029-12",salaryTaxPolicy:PAPER_SALARY_POLICY_2029.id,
        insuranceRateProxyFiscalYear:fixedInsurance.policy.proxyRateFiscalYear, indexedAllowanceAmountsAsOf:"2026-04",
        calculation:"年末の制度・固定世帯条件を12か月適用した比較。実際の2029年家計の予測ではない。"}} : {}),
      details:{headTax:ht, spouseTax:st, benefits, service, coverage,insurance:fixedInsurance ?? coverage,roles:assigned}};
  }

function classifyRevisionFalls(points) {
  const values = points.map(p => {
    if (!p || p.status === "insufficient") return null;
    const value = p.disposableWan;
    return Number.isFinite(value) ? value : null;
  });
  // 年間収支は円の整数。万円での二進小数の減算により比較・下落幅がぶれないようにする。
  const yen = values.map(v => v === null ? null : Math.round(v*WAN));
  const allFalls = [];
  for (let i=1; i<points.length; i++) {
    if (yen[i] === null || yen[i-1] === null || yen[i] >= yen[i-1]) continue;
    const a=points[i-1].breakdown, b=points[i].breakdown;
    const causes=[];
    if (b.tccaWan < a.tccaWan) causes.push("特別児童扶養手当");
    if (b.welfareWan < a.welfareWan) causes.push("障害児福祉手当");
    if (b.serviceWan > a.serviceWan) causes.push("障害福祉サービス・障害児通所支援の利用者負担");
    let j = i+1;
    // 取り戻す対象は「直前の給与点での世帯収支」。手当額だけの穴埋めではない。
    while (j<yen.length && yen[j] !== null && yen[j]<yen[i-1]) j++;
    const gap = j<yen.length && yen[j] === null;
    allFalls.push({at:i,delta:(yen[i-1]-yen[i])/WAN,recovered:j<yen.length && !gap ? j : null, ...(gap ? {recoveryStatus:"gap"} : {}),causes});
  }
  return {values, falls:allFalls.filter(f=>f.causes.length), allFalls};
}

function evaluateRevisionSlice(calculator, axis, fixedWan) {
  if (!["head","spouse"].includes(axis)) throw new RangeError("断面の給与軸が不正です。");
  const points=[];
  for (let i=0;i<=MAX_WAGE;i++) points.push(axis === "head" ? calculator.evaluate(i,fixedWan) : calculator.evaluate(fixedWan,i));
  return classifyRevisionFalls(points);
}

function healthGradeBandYen(grade) {
  if (!Number.isInteger(grade) || grade < 1 || grade > GRADES.length) throw new RangeError("健保の等級が範囲外です。");
  return {lower:GRADES[grade-1][0]*1000, upper:grade < GRADES.length ? GRADES[grade][0]*1000 : null};
}

function shortTimeWageTestFromAnnualPay(annualPayYen, year, month) {
  if (!Number.isSafeInteger(annualPayYen) || annualPayYen < 0 || ![2025,2026].includes(year) ||
      !Number.isInteger(month) || month < 1 || month > 12) throw new RangeError("年収（円）と対象年月が必要です。");
  if (year === 2026 && month >= 10) return {requirement:"abolished", monthlyThresholdYen:null, annualThresholdYen:null};
  const monthlyThresholdYen = 88000, annualThresholdYen = monthlyThresholdYen * 12;
  return {requirement:annualPayYen >= annualThresholdYen ? "met" : "not-met", monthlyThresholdYen, annualThresholdYen};
}

function employeeGradesFromAnnualPay(annualPayYen) {
  if (!Number.isSafeInteger(annualPayYen) || annualPayYen <= 0) throw new RangeError("本人加入時の正の年間給与（円）が必要です。");
  let idx = 0;
  while (idx + 1 < GRADES.length && annualPayYen >= 12000 * GRADES[idx + 1][0]) idx++;
  const healthStandardYen = GRADES[idx][1]*1000;
  return {healthGrade:idx+1, pensionGrade:Math.min(32,Math.max(1,idx-2)),
    healthStandardYen, pensionStandardYen:Math.min(650000,Math.max(88000,healthStandardYen))};
}

function resolveEmploymentContract(profile, salaryWan, year) {
  const pattern=profile?.workPattern;
  const unknown={mode:"unknown",employmentInsurance:null};
  if (!rates[year] || !Number.isInteger(salaryWan) || salaryWan<0 || salaryWan>1500 ||
      !["regular","short-covered","short-outside","under20"].includes(pattern)) return unknown;
  if (salaryWan===0 || pattern==="under20") return {mode:"outside",employmentInsurance:false};
  const region=profile.workRegion??"tokyo";
  if(!["tokyo","chiba"].includes(region)) return unknown;
  const minimumHours=pattern==="regular"?30:20;
  const hourlyMinimum=region==="tokyo" ? (year===2025?1226:1280) : (year===2025?1140:1195);
  if (salaryWan*10000 < minimumHours*52*hourlyMinimum) return {...unknown,reason:"この勤務時間で通年就労する場合の最低賃金に達しません。"};
  const eligible=pattern==="regular" || (pattern==="short-covered" &&
    shortTimeWageTestFromAnnualPay(salaryWan*10000,year,11).requirement!=="not-met");
  return {mode:eligible?"employee":"outside",employmentInsurance:true};
}

function payrollRound(numerator, denominator) {
  return Math.floor((numerator + denominator/2 - 1)/denominator);
}

function annualEmploymentPremium(salaryWan, year) {
  if (!rates[year] || !Number.isInteger(salaryWan) || salaryWan<0 || salaryWan>1500) throw new RangeError("給与・料率年度が対象外です。");
  const annual=salaryWan*10000, base=Math.floor(annual/12), extra=annual%12;
  return (12-extra)*payrollRound(base*rates[year].employment,10000)+extra*payrollRound((base+1)*rates[year].employment,10000);
}

function monthlyEmployeePremiums45Yen({remunerationYen,annualPayYen,year,month,workRegion} = {}) {
  if ((remunerationYen === undefined) === (annualPayYen === undefined) ||
      (remunerationYen !== undefined && (!Number.isSafeInteger(remunerationYen) || remunerationYen <= 0)) ||
      ![2025,2026].includes(year) || !Number.isInteger(month) || month < 1 || month > 12 ||
      (year === 2025 && month < 3) || !["chiba","tokyo"].includes(workRegion)) {
    throw new RangeError("報酬月額又は均等割する年収の一方、加入支部、保険料対象月（2025年3月～2026年12月）を指定してください。");
  }
  const tableYear = year === 2026 && month >= 3 ? 2026 : 2025;
  const r = rates[tableYear];
  const hc = workRegion === "chiba" ? (tableYear === 2025 ? 1138 : 1135) : r.healthCare;
  const supportRate = year === 2026 && month >= 4 ? r.support : 0;
  const grades=employeeGradesFromAnnualPay(annualPayYen ?? remunerationYen*12);
  const {healthStandardYen,pensionStandardYen}=grades;
  const healthCareYen = payrollRound(healthStandardYen * hc, 20000);
  // 厚労省「子ども・子育て支援金に関するQ&A」：合算後に折半・端数処理。配賦した差を別途足さない。
  const combinedHealthYen = payrollRound(healthStandardYen * (hc + supportRate), 20000);
  const pensionYen = payrollRound(pensionStandardYen * 1830, 20000);
  return {...grades,healthCareYen,supportYen:combinedHealthYen-healthCareYen,
    combinedHealthYen,pensionYen,totalYen:combinedHealthYen+pensionYen};
}

function annualEmployeePremiums(salaryWan, year, employmentInsurance, workRegion="tokyo") {
  if (!Number.isInteger(salaryWan) || salaryWan<=0 || salaryWan>1500 || !rates[year] || typeof employmentInsurance!=="boolean") throw new RangeError("本人加入の給与・年度・雇用保険の条件を確認してください。");
  // 既存の年額比較は4月分を12倍する。暦年に実際に支払う額とは区別する。
  const monthly=monthlyEmployeePremiums45Yen({annualPayYen:salaryWan*10000,year,month:4,workRegion});
  const employmentYen=employmentInsurance ? annualEmploymentPremium(salaryWan,year) : 0;
  return {workRegion,healthGrade:monthly.healthGrade,pensionGrade:monthly.pensionGrade,
    healthStandardYen:monthly.healthStandardYen,pensionStandardYen:monthly.pensionStandardYen,
    healthCareYen:12*monthly.healthCareYen,supportYen:12*monthly.supportYen,pensionYen:12*monthly.pensionYen,
    employmentYen,totalYen:12*monthly.totalYen+employmentYen};
}

function paymentCode(yen) {
  return !Number.isSafeInteger(yen) || yen < 0 ? 0 : yen > 0 ? 2 : 1;
}

function decisionCodes(point) {
  if (point?.status !== "calculated") return 0;
  const {benefits, service} = point.details ?? {};
  let cap = 0;
  if (service?.hasCapApplicableServiceUse) {
    // 実際の支払額が同じでも、利用するサービスの月額上限区分が変われば描く。
    const limit = service.householdCapYen;
    cap = limit === 0 ? 1 : limit === 4600 ? 2 : limit === 37200 ? 3 : 0;
  }
  return paymentCode(benefits?.tcca) | (paymentCode(benefits?.welfare) << 2) | (cap << 4);
}

function transition(previous, current, shift) {
  const a = (previous >> shift) & 3, b = (current >> shift) & 3;
  return a && b && a !== b ? (a << 2) | b : 0;
}

function changedSalaryDecisionSystems(previous,current) {
  return IDS.filter((_,i)=>transition(previous,current,2*i)!==0);
}

function buildSalaryDecisionMap(calculator, {maxSalaryWan = MAX, onProgress} = {}) {
  return collectDecisionMap(maxSalaryWan,(x,y)=>{
    const point=calculator.evaluate(x,y);
    return point?.status==="calculated"?decisionCodes(point):-1;
  },onProgress);
}

function buildSalaryDecisionMapFromGrid({width,decisionCodes:codes,validCount},changedX,changedY) {
  if(!(codes instanceof Uint8Array) || !(changedX instanceof Uint8Array) || !(changedY instanceof Uint8Array) ||
    [codes,changedX,changedY].some(a=>a.length!==width*width))
    throw new RangeError("制度境界の格子と変更マスクのサイズが一致しません。");
  const map=collectDecisionMap(width-1,(_x,_y,index)=>codes[index],null,changedX,changedY);
  return {...map,validCount};
}

function collectDecisionMap(maxSalaryWan,readCode,onProgress,changedX,changedY) {
  if (!Number.isInteger(maxSalaryWan) || maxSalaryWan < 0 || maxSalaryWan > MAX)
    throw new RangeError("給与上限は0～1,500万円の整数で指定してください。");
  const n = maxSalaryWan, width = n + 1;
  const layers = IDS.map(id => ({id, segments:[]}));
  const above = new Uint8Array(width);
  const openV = IDS.map(() => new Uint8Array(width)), startV = IDS.map(() => new Uint16Array(width));
  const openH = new Uint8Array(3), startH = new Uint16Array(3);
  /** 給与点を囲む半目盛の左端（または下端）を軸の表示範囲内に収める。 */
  const lower = i => Math.max(0, i - 0.5);
  /** 給与点を囲む半目盛の右端（または上端）を軸の表示範囲内に収める。 */
  const upper = i => Math.min(n, i + 0.5);
  let validCount = 0, previousPercent = 0;
  onProgress?.(0);
  for (let y = 0; y <= n; y++) {
    let left = 0;
    openH.fill(0);
    for (let x = 0; x <= n; x++) {
      const index=y*width+x,raw=index===0?-1:readCode(x,y,index);
      if(raw>=0) validCount++;
      const current = raw>=0?raw:0, up = above[x];
      for (let j = 0; j < IDS.length; j++) {
        const v = transition(left, current, 2*j), h = transition(up, current, 2*j);
        if(v && changedX)changedX[index]|=1<<j;
        if(h && changedY)changedY[index]|=1<<j;
        const lines = layers[j].segments;
        if (v !== openV[j][x]) {
          if (openV[j][x]) lines.push([x-0.5, lower(startV[j][x]), x-0.5, upper(y-1)]);
          openV[j][x] = v;
          if (v) startV[j][x] = y;
        }
        if (h !== openH[j]) {
          if (openH[j]) lines.push([lower(startH[j]), y-0.5, upper(x-1), y-0.5]);
          openH[j] = h;
          if (h) startH[j] = x;
        }
      }
      above[x] = current;
      left = current;
    }
    for (let j = 0; j < IDS.length; j++) {
      if (openH[j]) layers[j].segments.push([lower(startH[j]), y-0.5, n, y-0.5]);
    }
    const percent = Math.floor(100*(y+1)/width);
    if (percent !== previousPercent) { onProgress?.(percent); previousPercent = percent; }
  }
  for (let j = 0; j < IDS.length; j++) {
    for (let x = 1; x <= n; x++) {
      if (openV[j][x]) layers[j].segments.push([x-0.5, lower(startV[j][x]), x-0.5, n]);
    }
  }
  return {maxSalaryWan:n, validCount, layers};
}

function exactYen(value){
  if(!Number.isInteger(value)||value<=UNKNOWN_PLANE_NET_YEN||value>2147483647)
    throw new RangeError("給与格子の円額が整数の格納範囲外です。");
  return value;
}

function buildSalaryGraphDataset(inputs,{maxSalaryWan=1500,onProgress,createCalculator}={}){
  if(!Number.isInteger(maxSalaryWan)||maxSalaryWan<0||maxSalaryWan>1500)
    throw new RangeError("給与上限は0～1,500万円の整数で指定してください。");
  const width=maxSalaryWan+1,size=width*width;
  const netYen=new Int32Array(size).fill(UNKNOWN_PLANE_NET_YEN);
  const differenceYen=new Int32Array(size).fill(UNKNOWN_PLANE_NET_YEN),codes=new Uint8Array(size);
  const pair=createDisabilityIncomeComparison(inputs,{createCalculator});
  const income=buildSalarySurfaceGrid({evaluate(x,y){
    const index=y*width+x,{observedPoint,comparisonPoint}=pair.evaluatePair(x,y);
    if(observedPoint.status==="calculated"){
      netYen[index]=exactYen(Math.round(observedPoint.studyDisposableWan*10000));
      codes[index]=decisionCodes(observedPoint);
    }
    if(comparisonPoint.status==="calculated")differenceYen[index]=exactYen(comparisonPoint.differenceYen);
    return observedPoint;
  }},{maxSalaryWan,onProgress});
  // ここから先は各世帯の税・給付を再計算せず、前段で確定した金額と区分を読む。
  const missing={status:"excluded"},known={status:"calculated",differenceYen:0};
  const comparison=buildDisabilityDifferenceSurface({evaluate(x,y){
    const v=differenceYen[y*width+x];if(v===UNKNOWN_PLANE_NET_YEN)return missing;
    known.differenceYen=v;return known;
  }},{maxSalaryWan});
  const grid={width,netYen,differenceYen,decisionCodes:codes};
  const changedX=new Uint8Array(size),changedY=new Uint8Array(size);
  const map=buildSalaryDecisionMapFromGrid({...grid,validCount:income.validCount},changedX,changedY);
  map.outcomeLines=buildSalaryPlaneRecovery({width,netYen,changedX,changedY});
  return {income,comparison,map,grid};
}

function buildSalaryIncomeSection(calculator,{axis="head",fixedWan,maxSalaryWan=1500}={}) {
  if(!["head","spouse"].includes(axis))throw new RangeError("給与を動かす軸は世帯主か配偶者を指定してください。");
  if(![fixedWan,maxSalaryWan].every(v=>Number.isInteger(v)&&v>=0&&v<=1500))
    throw new RangeError("固定給与と走査上限は0～1,500万円の整数で指定してください。");
  const points=Array(maxSalaryWan+1).fill(null),events=[];
  let prevCode=0;
  for(let wage=0;wage<=maxSalaryWan;wage++){
    const p=wage===0&&fixedWan===0?null:axis==="head"?calculator.evaluate(wage,fixedWan):calculator.evaluate(fixedWan,wage);
    if(p?.status!=="calculated"){prevCode=0;continue;}
    if(!Number.isFinite(p.studyDisposableWan))throw new TypeError("算定済み点には可処分所得が必要です。");
    const afterYen=Math.round(p.studyDisposableWan*10000);
    if(!Number.isSafeInteger(afterYen))throw new RangeError("可処分所得を円単位に変換できません。");
    points[wage]=afterYen;
    const code=decisionCodes(p),systems=changedSalaryDecisionSystems(prevCode,code);
    prevCode=code;
    if(!systems.length)continue;
    const beforeYen=points[wage-1],dropYen=Math.max(0,beforeYen-afterYen);
    events.push({beforeWan:wage-1,afterWan:wage,beforeYen,afterYen,systems,dropYen,
      retreatWan:null,retreatAtWan:null,recoveryWan:null,recoveryAtWan:null,interveningDrops:0});
  }
  const dropAt=new Set(events.filter(e=>e.dropYen>0).map(e=>e.afterWan));
  for(const e of events){
    if(e.dropYen===0)continue;
    // 離散格子では同額点が存在するとは限らない。下落直後の水準以下だった最後の給与点を選ぶ。
    for(let k=e.beforeWan;k>=0&&points[k]!==null;k--){
      if(points[k]<=e.afterYen){e.retreatAtWan=k;e.retreatWan=e.afterWan-k;break;}
    }
    // 他制度の境界を越えても追跡する。元の水準以上に初めて戻った点で打ち切り、欠測はまたがない。
    for(let k=e.afterWan+1;k<=maxSalaryWan&&points[k]!==null;k++){
      if(points[k]>=e.beforeYen){e.recoveryAtWan=k;e.recoveryWan=k-e.afterWan;break;}
      if(dropAt.has(k))e.interveningDrops++;
    }
  }
  return {axis,fixedWan,maxSalaryWan,points,events};
}

function buildSalaryPlaneRecovery({width,netYen,changedX,changedY}={}) {
  if (!Number.isSafeInteger(width) || width<1 || width>1501 ||
      !(netYen instanceof Int32Array) || !(changedX instanceof Uint8Array) || !(changedY instanceof Uint8Array) ||
      [netYen,changedX,changedY].some(a=>a.length!==width*width))
    throw new RangeError("給与格子の幅・配列の長さ・型が一致しません。");

  /** 片方の親の給与を1万円ずつ増やし、すべての他方給与について制度変更時の下落・初回回復を抽出する。 */
  const byDirection = (alongX,changes) => {
    const drop=[],recovery=[],dropMasks=[],recoveryDropIndex=[];
    const stack=new Int32Array(width), next=new Int32Array(width);
    for(let fixed=0;fixed<width;fixed++){
      const base=alongX?fixed*width:fixed, step=alongX?1:width;
      // 右から見る単調スタック。等値は捨てない（「回復」は超過ではなく以上）。
      // 各点は一度だけpushされ、popも高々一度。各断面O(width)。
      let count=0;
      for(let k=width-1;k>=0;k--){
        const i=base+k*step,v=netYen[i];
        if(changes[i]>7)throw new RangeError("制度切替えのビットマスクが不正です。");
        if(v===UNKNOWN_PLANE_NET_YEN){count=0;next[k]=-1;continue;}
        while(count && netYen[base+stack[count-1]*step]<v)count--;
        next[k]=count?stack[count-1]:-1;
        stack[count++]=k;
      }
      const lo=Math.max(0,fixed-.5),hi=Math.min(width-1,fixed+.5);
      /** 切替えを観測した給与kの直前の半目盛に、給与軸の向きに応じた線分を置く。 */
      const line=k=>alongX?[k-.5,lo,k-.5,hi]:[lo,k-.5,hi,k-.5];
      for(let k=1;k<width;k++){
        const i=base+k*step, before=netYen[i-step],after=netYen[i],mask=changes[i];
        if(!mask || before===UNKNOWN_PLANE_NET_YEN || after===UNKNOWN_PLANE_NET_YEN || after>=before)continue;
        const dropIndex=drop.length, firstRecovered=next[k-1];
        drop.push(line(k)); dropMasks.push(mask);
        if(firstRecovered!==-1){
          recovery.push(line(firstRecovered));
          recoveryDropIndex.push(dropIndex);
        }
      }
    }
    return {drop,recovery,dropMasks,recoveryDropIndex};
  };
  return {head:byDirection(true,changedX),spouse:byDirection(false,changedY)};
}

