function buildSalarySurfaceGrid(calculator, {maxSalaryWan = MAX_SURFACE_SALARY_WAN, onProgress} = {}) {
  if (!Number.isInteger(maxSalaryWan) || maxSalaryWan < 0 || maxSalaryWan > MAX_SURFACE_SALARY_WAN) {
    throw new RangeError("給与格子の上限は0～1,500万円の整数で指定してください。");
  }
  const width = maxSalaryWan + 1, total = width * width;
  const heights = new Float32Array(total);
  const allPoints=[],allLines=[];
  // 現在・左隣・真上の3制度の年額（整数円）。直近1行＋1点だけを循環利用する。
  const windowSize=width+1, amounts=new Int32Array(windowSize*SURFACE_AMOUNT_COUNT).fill(UNKNOWN_SURFACE_AMOUNT);
  const headMarksAbove = new Uint8Array(width);
  const layers = SURFACE_SYSTEMS.map(()=>({points:[],lines:[]}));
  const rowsPerUpdate = Math.ceil(width / 100);
  let min = Infinity, max = -Infinity, validCount = 0;
  onProgress?.(0, total);
  for (let spouse = 0; spouse < width; spouse++) {
    const rowStart = spouse * width;
    let spouseMarksLeft=0;
    for (let head = 0; head < width; head++) {
      const index = rowStart + head;
      const slot=index%windowSize, offset=slot*SURFACE_AMOUNT_COUNT;
      if (index === 0) { heights[index] = NaN; continue; }
      const point = calculator.evaluate(head, spouse);
      if (point.status !== "calculated" || !Number.isFinite(point.studyDisposableWan)) {
        heights[index] = NaN;
        amounts.fill(UNKNOWN_SURFACE_AMOUNT,offset,offset+SURFACE_AMOUNT_COUNT);
        headMarksAbove[head]=spouseMarksLeft=0;
        continue;
      }
      writeSurfaceAmounts(amounts,offset,point);
      const h=head===0?0:surfaceChangeMask(amounts,((slot+windowSize-1)%windowSize)*SURFACE_AMOUNT_COUNT,offset);
      const s=spouse===0?0:surfaceChangeMask(amounts,((slot+1)%windowSize)*SURFACE_AMOUNT_COUNT,offset);
      if (h|s) {
        // 各制度を独立に接続。別の制度の給与点や欠測を使用しない。
        const vertical=h & headMarksAbove[head], horizontal=s & spouseMarksLeft;
        allPoints.push(index);
        if (vertical) allLines.push(index-width,index);
        if (horizontal) allLines.push(index-1,index);
        for (let j=0;j<layers.length;j++) {
          const bit=SURFACE_SYSTEMS[j].bit, layer=layers[j];
          if ((h|s)&bit) layer.points.push(index);
          if (vertical&bit) layer.lines.push(index-width,index);
          if (horizontal&bit) layer.lines.push(index-1,index);
        }
      }
      headMarksAbove[head]=h; spouseMarksLeft=s;
      // 表示する格子の極値は送信する Float32 の値に揃える。
      const z = Math.fround(point.studyDisposableWan);
      heights[index] = z;
      if (z < min) min = z;
      if (z > max) max = z;
      validCount++;
    }
    const finishedRows = spouse + 1;
    if (finishedRows === width || finishedRows % rowsPerUpdate === 0) {
      onProgress?.(finishedRows * width, total);
    }
  }
  const changeBySystem=Object.fromEntries(layers.map(({points,lines},i)=>[SURFACE_SYSTEMS[i].id,
    {points:Uint32Array.from(points),lines:Uint32Array.from(lines)}]));
  return {width, heights, changePoints:Uint32Array.from(allPoints), changeLines:Uint32Array.from(allLines),
    changeBySystem, min:validCount ? min : null, max:validCount ? max : null, validCount};
}

function writeSurfaceAmounts(target,offset,point) {
  const {benefits,service}=point.details ?? {};
  const a=benefits?.tcca,b=benefits?.welfare,c=service?.annual;
  target[offset]=Number.isSafeInteger(a) && a>=0 ? a : UNKNOWN_SURFACE_AMOUNT;
  target[offset+1]=Number.isSafeInteger(b) && b>=0 ? b : UNKNOWN_SURFACE_AMOUNT;
  target[offset+2]=Number.isSafeInteger(c) && c>=0 ? c : UNKNOWN_SURFACE_AMOUNT;
}

function surfaceChangeMask(amounts,offsetA,offsetB) {
  let mask=0;
  for(let i=0;i<SURFACE_AMOUNT_COUNT;i++) {
    const a=amounts[offsetA+i],b=amounts[offsetB+i];
    if (a!==b && a!==UNKNOWN_SURFACE_AMOUNT && b!==UNKNOWN_SURFACE_AMOUNT) mask|=SURFACE_SYSTEMS[i].bit;
  }
  return mask;
}

function allowanceState(c,child,stopped) {
  const amount=c.assessmentIncomeYen ?? c.incomeYen;
  const role=c.role==="spouse"?(child?"受給児童の配偶者":"受給資格者の配偶者"):(roles[c.role] ?? "所得判定");
  return (child?child+"・":"")+role+"（"+person(c.id)+"）："+
    (stopped?"所得制限に該当":"所得制限に該当しない")+
    (Number.isFinite(amount)&&Number.isFinite(c.limitYen)?"（判定所得"+yen(amount)+"／限度額"+yen(c.limitYen)+"）":"");
}

function capState(s) {
  const cat=({0:"非課税等",4600:"一般1",37200:"一般2"})[s.householdCapYen];
  return "年額負担"+yen(s.annual)+"（月額実負担"+yen(s.monthly)+"）。"+cat+"：月額上限"+yen(s.householdCapYen)+
    (Number.isFinite(s.assessmentLevyYen)?"（世帯の判定用市町村民税所得割 "+yen(s.assessmentLevyYen)+"）":"");
}

function describeSurfaceChanges(before,after) {
  if ([before,after].some(p=>p?.status!=="calculated" || !Number.isFinite(p.studyDisposableWan))) return [];
  const amounts=new Int32Array(2*SURFACE_AMOUNT_COUNT);
  writeSurfaceAmounts(amounts,0,before);
  writeSurfaceAmounts(amounts,SURFACE_AMOUNT_COUNT,after);
  const mask=surfaceChangeMask(amounts,0,SURFACE_AMOUNT_COUNT);
  if (!mask) return [];
  const rows=[], a=before.details,b=after.details;
  /** 世帯の支給額変更を説明するのに必要な、判定前後で結論の変わった人だけを列挙する。 */
  function compareReasons(prior,next,field,child,oldReasons,newReasons) {
    (next ?? []).forEach((c,i)=>{
      const p=prior?.[i];
      if (!p || typeof p[field]!=="boolean" || typeof c[field]!=="boolean" || p[field]===c[field]) return;
      oldReasons.push(allowanceState(p,child,field==="stopped"?p.stopped:!p.passes));
      newReasons.push(allowanceState(c,child,field==="stopped"?c.stopped:!c.passes));
    });
  }
  /** 複数人・複数児の判定に変化があっても、世帯の年額は各制度につき一度だけ示す。 */
  function addBenefit(sys,prior,next,oldReasons,newReasons) {
    rows.push({id:sys.id,before:["世帯への年額支給"+yen(prior),...oldReasons].join("。"),
      after:["世帯への年額支給"+yen(next),...newReasons].join("。")});
  }
  if (mask & special.bit) {
    const oldReasons=[],newReasons=[];
    compareReasons(a.benefits.specialChildAllowance?.checks,b.benefits.specialChildAllowance?.checks,"stopped","",oldReasons,newReasons);
    addBenefit(special,a.benefits.tcca,b.benefits.tcca,oldReasons,newReasons);
  }
  if (mask & welfare.bit) {
    const oldReasons=[],newReasons=[];
    (b.benefits.welfareChildren ?? []).forEach((c,i)=>{
      const prev=a.benefits.welfareChildren?.[i];
      if (!prev || prev.annualYen===c.annualYen) return;
      compareReasons(prev.checks,c.checks,"passes","子"+(i+1),oldReasons,newReasons);
    });
    addBenefit(welfare,a.benefits.welfare,b.benefits.welfare,oldReasons,newReasons);
  }
  if (mask & services.bit) rows.push({id:services.id,before:capState(a.service),after:capState(b.service)});
  return rows;
}

function compareReasons(prior,next,field,child,oldReasons,newReasons) {
    (next ?? []).forEach((c,i)=>{
      const p=prior?.[i];
      if (!p || typeof p[field]!=="boolean" || typeof c[field]!=="boolean" || p[field]===c[field]) return;
      oldReasons.push(allowanceState(p,child,field==="stopped"?p.stopped:!p.passes));
      newReasons.push(allowanceState(c,child,field==="stopped"?c.stopped:!c.passes));
    });
  }

function addBenefit(sys,prior,next,oldReasons,newReasons) {
    rows.push({id:sys.id,before:["世帯への年額支給"+yen(prior),...oldReasons].join("。"),
      after:["世帯への年額支給"+yen(next),...newReasons].join("。")});
  }

function calcServiceAssessmentLevyYen(municipalIncomeLevyYen, dependentAges) {
  const reliefYen = dependentAges.reduce((sum, age) => sum + (age < 16 ? 19800 : age < 19 ? 7200 : 0), 0);
  return Math.max(0, Math.round(municipalIncomeLevyYen) - reliefYen);
}

function getChildDayServiceCapYen(assessmentLevyYen, householdTaxable) {
  if (!householdTaxable) return 0;
  return assessmentLevyYen < 280000 ? 4600 : 37200;
}

function calculateSocialInsuranceComponents(salaryWan, age, scenarioKey) {
  const salary = Math.max(0, toNumber(salaryWan, 0));
  const rates = SOCIAL_RATE_RULES[normalizeScenario(scenarioKey)] || SOCIAL_RATE_RULES.s2;
  const healthBasisWan = salary >= HEALTH_CAP_THRESHOLD_WAN ? HEALTH_MAX_STANDARD_ANNUAL_WAN : salary;
  const pensionBasisWan = salary >= PENSION_CAP_THRESHOLD_WAN ? PENSION_MAX_STANDARD_ANNUAL_WAN : salary;
  const careRate = toNumber(age, 0) >= 40 ? rates.care : 0;
  const healthWan = healthBasisWan * rates.health;
  const careWan = healthBasisWan * careRate;
  const childSupportContributionWan = healthBasisWan * rates.support;
  const pensionWan = pensionBasisWan * rates.pension;
  const employmentWan = salary * rates.employment;
/**
   * 小数の料率を百分率の説明文字列へ変換する。
   * @remarks 社会保険料・表示。単位: %（小数4桁丸め）。式・境界条件・丸めは移動前の実装を維持。
   * @param {*} rate 判定対象・区分または補助値（呼出側の定義に従う）
   * @returns {*} string。単位: %（小数4桁丸め）
   */
  const percent = (rate) => `${roundWan(rate * 100, 4)}%`;
  return {
    salaryWan: salary,
    healthBasisWan,
    pensionBasisWan,
    rates: { ...rates, care: careRate },
    healthWan,
    careWan,
    childSupportContributionWan,
    pensionWan,
    employmentWan,
    formulas: {
      health: `${roundWan(healthBasisWan, 4)}万 × ${percent(rates.health * 2)} ÷ 2`,
      care: careRate > 0
        ? `${roundWan(healthBasisWan, 4)}万 × ${percent(careRate * 2)} ÷ 2`
        : "40歳未満のため適用なし",
      support: `${roundWan(healthBasisWan, 4)}万 × ${percent(rates.support * 2)} ÷ 2`,
      pension: `${roundWan(pensionBasisWan, 4)}万 × ${percent(rates.pension * 2)} ÷ 2`,
      employment: `${roundWan(salary, 4)}万 × ${percent(rates.employment)}`,
      total: "B2a ＋ B2b ＋ B2c ＋ B2d ＋ B2e",
    },
    totalWan: healthWan + careWan + childSupportContributionWan + pensionWan + employmentWan,
  };
}

function describeSocialInsuranceDeduction(salaryWan, age, scenarioKey, totalWan, exemptSocial) {
  const s = Math.max(0, toNumber(salaryWan, 0));
  const incomeYen = Math.round(s * 10000);
  const skey = normalizeScenario(scenarioKey);
  const ageKey = toNumber(age, 0) >= 40 ? "o40" : "u40";
  const components = calculateSocialInsuranceComponents(s, age, skey);
  const base = {
    salaryWan: s,
    roundedSalaryWan: Math.round(s),
    age: toNumber(age, 0),
    ageBand: ageKey,
    scenario: skey,
    totalWan: toNumber(totalWan, 0),
    source: "social_u40/social_o40 generated from bracket formulas",
    approximation: "年収を算定基礎とする率ベース近似（賞与なし）",
    components,
  };
  if (exemptSocial) {
    return { ...base, bracketLabel: "130万円以下・被扶養扱い", rate: 0, interceptYen: 0, fixedAnnualYen: 0, formula: "130万円以下の被扶養扱いで0" };
  }
  if (incomeYen <= 0) {
    return { ...base, bracketLabel: "0円", rate: 0, interceptYen: 0, fixedAnnualYen: 0, formula: "給与収入0のため社会保険料0" };
  }
  const bracketLabel =
    s >= HEALTH_CAP_THRESHOLD_WAN
      ? "健康保険等・厚生年金とも上限到達"
      : s >= PENSION_CAP_THRESHOLD_WAN
        ? "厚生年金の上限到達"
        : "各制度の本人負担率を適用";
  return {
    ...base,
    bracketLabel,
    rate: null,
    interceptYen: null,
    fixedAnnualYen: null,
    formula: "健保 + 介護 + 子ども・子育て支援金 + 厚生年金 + 雇用保険",
  };
}

function natural(value, label) {
  if (!Number.isSafeInteger(value) || value < 0) throw new RangeError(label + "には0以上の整数が必要です。");
  return value;
}

function salaryOnlySpecialChildIncome({salaryIncomeBeforeAdjustmentYen, spouseSpecialDeductionYen,
  ordinaryDisabilityCount, specialDisabilityCount}) {
  const salary = natural(salaryIncomeBeforeAdjustmentYen,"前年給与所得");
  const spouse = natural(spouseSpecialDeductionYen,"配偶者特別控除");
  const ordinary = natural(ordinaryDisabilityCount,"障害者数");
  const special = natural(specialDisabilityCount,"特別障害者数");
  return Math.max(0, Math.max(0,salary-100000) - 80000 - spouse - ordinary*270000 - special*400000);
}

function calculateSpecialChildAllowance({grades, claimant, spouse, otherObligors=[],
  additionalMaintainedChildren=0, claimantOlderTaxDependents=0}) {
  if (!Array.isArray(grades) || grades.length < 1 || grades.length > 3 ||
      grades.some(g=>!["not","1","2"].includes(g))) throw new RangeError("児童1～3人の認定等級が必要です。");
  if (!Array.isArray(otherObligors)) throw new TypeError("扶養義務者は配列で指定してください。");
  const extra = natural(additionalMaintainedChildren,"税扶養外の前年末生計維持児童数");
  const older = natural(claimantOlderTaxDependents,"受給資格者の16～18歳の控除対象扶養親族数");
  const count = natural(claimant.dependentCount,"受給資格者の扶養親族等の数");
  if (older > count || older + extra > grades.length) throw new RangeError("生計維持児童・年齢加算の人数が不正です。");
  const claimantLimit = 4596000 + (count+extra)*380000 + older*250000;
  const seen = new Set();
  /** 人の重複を検出し、この1人の判定所得が指定された限度額以上かを記録する。 */
  function check(p, role, limitYen) {
    if (typeof p.id !== "string" || !p.id || seen.has(p.id)) throw new TypeError("所得判定対象は各人1回だけ指定してください。");
    seen.add(p.id);
    const assessmentIncomeYen = natural(p.assessmentIncomeYen,"前年の判定所得");
    return {id:p.id, role, dependentCount:p.dependentCount, assessmentIncomeYen, limitYen,
      stopped:assessmentIncomeYen >= limitYen};
  }
  /** 配偶者・同一生計の扶養義務者自身の扶養人数から法7条の限度額を求めて照合する。 */
  function checkOther(p, role) {
    const n = natural(p.dependentCount,"配偶者・扶養義務者の扶養親族等の数");
    return check(p, role, n === 0 ? 6287000 : 6323000 + 213000*n);
  }
  const checks = [check(claimant,"claimant",claimantLimit), checkOther(spouse,"spouse"),
    ...otherObligors.map(p=>checkOther(p,"obligor"))];
  const stoppedBy = checks.filter(person=>person.stopped);
  const monthlyBeforeIncomeYen = grades.reduce((total, g)=>total+monthlyByGrade[g],0);
  const monthlyYen = stoppedBy.length ? 0 : monthlyBeforeIncomeYen;
  return {basis:specialChildAllowanceBasis, checks, stoppedBy, incomeEligible:stoppedBy.length===0,
    status:monthlyBeforeIncomeYen===0 ? "no-qualifying-child" : stoppedBy.length ? "income-stopped" : "payable",
    monthlyBeforeIncomeYen, monthlyYen, annualYen:12*monthlyYen};
}

function check(p, role, limitYen) {
    if (typeof p.id !== "string" || !p.id || seen.has(p.id)) throw new TypeError("所得判定対象は各人1回だけ指定してください。");
    seen.add(p.id);
    const assessmentIncomeYen = natural(p.assessmentIncomeYen,"前年の判定所得");
    return {id:p.id, role, dependentCount:p.dependentCount, assessmentIncomeYen, limitYen,
      stopped:assessmentIncomeYen >= limitYen};
  }

function checkOther(p, role) {
    const n = natural(p.dependentCount,"配偶者・扶養義務者の扶養親族等の数");
    return check(p, role, n === 0 ? 6287000 : 6323000 + 213000*n);
  }

function rowAtKeyInt(arr, key, xInt) {
  if (!arr || arr.length === 0) return null;
  const idx = clampInt(xInt, 0, arr.length - 1);
  const r = arr[idx];
  if (r && Number(r[key]) === idx) return r;

  let best = arr[0];
  let min = Math.abs((arr[0][key] ?? 0) - xInt);
  for (const rr of arr) {
    const d = Math.abs((rr[key] ?? 0) - xInt);
    if (d < min) {
      min = d;
      best = rr;
    }
  }
  return best;
}

function interpTableValue(arr, xKey, xVal, yKey) {
  const x = Number(xVal);
  if (!Number.isFinite(x) || !arr || arr.length === 0) return 0;
  const lo = Math.floor(x);
  const hi = Math.ceil(x);
  const r0 = rowAtKeyInt(arr, xKey, lo);
  const r1 = rowAtKeyInt(arr, xKey, hi);
  const y0 = Number(r0?.[yKey]) || 0;
  const y1 = Number(r1?.[yKey]) || 0;
  if (hi === lo) return y0;
  const t = (x - lo) / (hi - lo);
  return y0 + (y1 - y0) * t;
}

function calcEmploymentIncomeDeductionR8FinalWan(salaryWan) {
  const salaryYen = Math.max(0, Math.round(toNumber(salaryWan, 0) * 10000));
  return (salaryYen - salaryIncomeBeforeAdjustmentYen(salaryYen, 2026)) / 10000;
}

function calcBasicIncomeTaxDeductionR8FinalWan(totalIncomeWan) {
  const yen = Math.round(Math.max(0, toNumber(totalIncomeWan, 0)) * 10000);
  if (yen <= 4890000) return 104;
  if (yen <= 6550000) return 67;
  if (yen <= 23500000) return 62;
  if (yen <= 24000000) return 48;
  if (yen <= 24500000) return 32;
  if (yen <= 25000000) return 16;
  return 0;
}

function calcIncomeAdjustmentDeductionWan(salaryWan, eligible) {
  const t = toNumber(salaryWan, 0);
  if (!eligible) return 0;
  if (t <= 850) return 0;
  const capped = Math.min(1000, t);
  return Math.min(15, Math.max(0, (capped - 850) * 0.1));
}

function describeEmploymentIncomeDeduction(salaryWan, scenarioKey, tableWan, incomeAdjustmentWan) {
  const s = Math.max(0, toNumber(salaryWan, 0));
  const skey = normalizeScenario(scenarioKey);
  const baseWan = toNumber(tableWan, 0);
  const minByScenario = {
    s1: { amountWan: 55, upperWan: 162, bracketLabel: "162万円以下" },
    s2: { amountWan: 65, upperWan: 190, bracketLabel: "190万円以下" },
    s3: { amountWan: 74, upperWan: 220, bracketLabel: "220万円以下" },
    s4: { amountWan: 74, upperWan: 220, bracketLabel: "220万円以下（年末調整表の端数処理あり）" },
  };
  const min = minByScenario[skey] || minByScenario.s2;
  let detail;
  if (s <= 0) {
    detail = {
      bracketLabel: "0円",
      rate: 0,
      interceptWan: 0,
      capWan: null,
      isCapped: false,
      formula: "給与収入0のため給与所得控除0",
      formulaValueWan: 0,
    };
  } else if (s <= min.upperWan) {
    detail = {
      bracketLabel: min.bracketLabel,
      rate: 0,
      interceptWan: min.amountWan,
      capWan: null,
      isCapped: false,
      formula: `${min.amountWan}万円(最低保障)`,
      formulaValueWan: min.amountWan,
    };
  } else if (s <= 180) {
    detail = {
      bracketLabel: "162万円超180万円以下",
      rate: 0.4,
      interceptWan: -10,
      capWan: null,
      isCapped: false,
      formula: "収入×0.40 − 10万円",
      formulaValueWan: roundWan(s * 0.4 - 10, 4),
    };
  } else if (s < 360) {
    detail = {
      bracketLabel: "180万円超360万円未満",
      rate: 0.3,
      interceptWan: 8,
      capWan: null,
      isCapped: false,
      formula: "収入×0.30 + 8万円",
      formulaValueWan: roundWan(s * 0.3 + 8, 4),
    };
  } else if (s < 660) {
    detail = {
      bracketLabel: "360万円以上660万円未満",
      rate: 0.2,
      interceptWan: 44,
      capWan: null,
      isCapped: false,
      formula: "収入×0.20 + 44万円",
      formulaValueWan: roundWan(s * 0.2 + 44, 4),
    };
  } else if (s <= 850) {
    detail = {
      bracketLabel: "660万円以上850万円以下",
      rate: 0.1,
      interceptWan: 110,
      capWan: 195,
      isCapped: false,
      formula: "収入×0.10 + 110万円",
      formulaValueWan: roundWan(s * 0.1 + 110, 4),
    };
  } else {
    detail = {
      bracketLabel: "850万円超",
      rate: 0.1,
      interceptWan: 110,
      capWan: 195,
      isCapped: true,
      rawFormulaWan: roundWan(s * 0.1 + 110, 4),
      formula: "min(195万円, 収入×0.10 + 110万円)",
      formulaValueWan: 195,
    };
  }
  return {
    ...detail,
    salaryWan: s,
    roundedSalaryWan: skey === "s4" ? null : Math.round(s),
    calculationMethod: skey === "s4" ? "令和8年分給与所得法定表から所得金額を計算（万円単位に丸めない）" : "旧万円刻みテーブル参照",
    tableValueWan: baseWan,
    incomeAdjustmentDeductionWan: toNumber(incomeAdjustmentWan, 0),
    incomeAdjustmentFormula:
      toNumber(incomeAdjustmentWan, 0) > 0
        ? `(${roundWan(s, 4)}万 − 850万) × 10%（上限15万）`
        : "適用なし",
    totalDeductionWan: baseWan + toNumber(incomeAdjustmentWan, 0),
    employmentIncomeWan: Math.max(0, s - baseWan - toNumber(incomeAdjustmentWan, 0)),
    source: skey === "s4" ? CALCULATION_SOURCES.employmentIncomeR8Final : CALCULATION_SOURCES.incomeTax,
  };
}

